                eprintln!();
                match e {
                    ParseError::NoData => {
                        eprintln!("Caused by:\n    no character data found, did you forget to write it?");
                    },
                    ParseError::NotForm(inner) => {
                        if inner.is_empty() {
                            // For "-": inner empty, but we show empty? Actually for skip -foo, inner "foo" shown.
                            // For our case, if original was "-foo", inner is "foo", but we have s = "-foo", inner = "foo"
                            // The cause should show inner without minus
                            // For empty after minus? We have inner empty string? Then NotForm with empty?
                            eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner);
                        } else {
                            eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner);
                        }
                    },
                    ParseError::InvalidUnit(u) => {
                        eprintln!("Caused by:\n    invalid unit \"{}\"", u);
                    },
                    ParseError::FailedIntegerPart(_, detail) => {
                        if detail == "cannot parse integer from empty string" {
                            eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", detail);
                        } else {
                            eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", detail);
                        }
                    },
                    _ => {
                        eprintln!("Caused by:\n    {}", e);
                    }
                }
                std::process::exit(1);
            }
        }
    } else {
