fn map_char(b: u8, table: CharacterTable) -> char {
    match table {
        CharacterTable::Ascii => {
            if b == 0x20 {
                ' '
            } else if b >= 0x21 && b <= 0x7e {
                b as char
            } else {
                '.'
            }
        },
        CharacterTable::Default => {
            if b == 0x00 {
                '⋄'
            } else if b == 0x09 || b == 0x0a || b == 0x0c || b == 0x0d {
                '_'
            } else if b == 0x20 {
                ' '
            } else if b >= 0x21 && b <= 0x7e {
                b as char
            } else if b == 0x0b || (b >= 0x0e && b <= 0x1f) || b == 0x7f || (b >= 0x01 && b <= 0x08) {
                '•'
            } else {
                '×'
            }
        },
        CharacterTable::Braille => {
            if b == 0x00 {
                '⋄'
            } else if b == 0x09 {
                '→'
            } else if b == 0x0a {
                '↵'
            } else if b == 0x0d {
                '←'
            } else if b >= 0x20 && b <= 0x7e {
                b as char
            } else if b <= 0x1f {
                // Braille for control chars
