fn handle_include(file_opt: Option<PathBuf>, skip_opt: Option<i64>, length_opt: Option<u64>, block_size: u64) {
    // Determine input data
    let mut data: Vec<u8> = Vec::new();
    let mut file_name: Option<String> = None;
    let mut file_size: Option<u64> = None;

    if let Some(ref path) = file_opt {
        let metadata = match std::fs::metadata(path) {
            Ok(m) => m,
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        };
        file_size = Some(metadata.len());
        file_name = Some(path.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string());

        let mut file = match File::open(path) {
            Ok(f) => f,
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        };

        // Skip
        let mut skip_val: u64 = 0;
        if let Some(s) = skip_opt {
            if s >=0 {
                skip_val = s as u64;
                if let Err(_) = file.seek(SeekFrom::Start(skip_val)) {
                    eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                    std::process::exit(1);
                }
            } else {
                let size = file_size.unwrap() as i64;
                let new_pos = size + s;
                if new_pos <0 {
                    eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                    std::process::exit(1);
                }
                skip_val = new_pos as u64;
                if let Err(_) = file.seek(SeekFrom::Start(skip_val)) {
                    eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                    std::process::exit(1);
                }
            }
        }

        if let Some(len) = length_opt {
            let mut buf = vec![0u8; len as usize];
            let n = match file.read(&mut buf) {
                Ok(n) => n,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            };
            buf.truncate(n);
            data = buf;
        } else {
            if let Err(e) = file.read_to_end(&mut data) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        // stdin
        let mut stdin = io::stdin();
        if let Some(s) = skip_opt {
            if s <0 {
                eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                std::process::exit(1);
            } else {
                let mut discard = s as u64;
                let mut buf = [0u8; 8192];
                while discard >0 {
                    let to_read = std::cmp::min(discard, buf.len() as u64) as usize;
                    match stdin.read(&mut buf[..to_read]) {
                        Ok(0) => break,
                        Ok(n) => discard -= n as u64,
                        Err(e) => {
                            eprintln!("Error: {}", e);
                            std::process::exit(1);
                        }
                    }
                }
            }
        }
        if let Some(len) = length_opt {
            let mut buf = vec![0u8; len as usize];
            let mut total =0;
            while total < len as usize {
                let to_read = (len as usize)-total;
                let n = match stdin.read(&mut buf[total..total+to_read]) {
                    Ok(n) => n,
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        std::process::exit(1);
                    }
                };
                if n==0 { break; }
                total+=n;
            }
            buf.truncate(total);
            data=buf;
        } else {
            if let Err(e) = stdin.read_to_end(&mut data) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    }

    // Now output include style
    let mut stdout = io::stdout();
    if let Some(fname) = file_name {
        // Sanitize file name to C identifier
        let sanitized = sanitize_filename(&fname);
        if data.is_empty() {
            writeln!(stdout, "unsigned char {}[] = {{", sanitized).unwrap();
            writeln!(stdout, "").unwrap();
            writeln!(stdout, "}};").unwrap();
            writeln!(stdout, "unsigned int {}_len = 0;", sanitized).unwrap();
        } else {
            writeln!(stdout, "unsigned char {}[] = {{", sanitized).unwrap();
            // Print bytes 12 per line
            for (i, chunk) in data.chunks(12).enumerate() {
                let mut line = String::new();
                line.push_str("  ");
                for (j, b) in chunk.iter().enumerate() {
                    line.push_str(&format!("0x{:02x}", b));
                    if i*12 + j +1 < data.len() {
                        line.push(',');
                    }
                    if j+1 < chunk.len() {
                        line.push(' ');
                    }
                }
                writeln!(stdout, "{}", line).unwrap();
            }
            writeln!(stdout, "}};").unwrap();
            writeln!(stdout, "unsigned int {}_len = {};", sanitized, data.len()).unwrap();
        }
    } else {
        // stdin: no header, only hex list?
        if data.is_empty() {
            // No output? Original showed empty for stdin empty include
            return;
        }
        for (i, chunk) in data.chunks(12).enumerate() {
            let mut line = String::new();
            line.push_str("  ");
            for (j, b) in chunk.iter().enumerate() {
                line.push_str(&format!("0x{:02x}", b));
                if i*12 + j +1 < data.len() {
                    line.push(',');
                }
                if j+1 < chunk.len() {
                    line.push(' ');
                }
            }
            writeln!(stdout, "{}", line).unwrap();
        }
    }
}

fn sanitize_filename(name: &str) -> String {
    let mut s = String::new();
    for c in name.chars() {
        if c.is_ascii_alphanumeric() || c == '_' {
            s.push(c);
        } else {
            s.push('_');
        }
    }
    // If name doesn't contain any alphanumeric? Keep as is
    s
}
