// Byte count parsing

#[derive(Debug)]
enum ParseError {
    NoData,
    NotForm(String),
    InvalidUnit(String),
    NegativeNotAllowed,
    FailedIntegerPart(String, String), // (cause type, detail)
    BlockSizeMustBePositive,
    BlockSizeCannotUseBlock,
}

impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::NoData => write!(f, "no character data found, did you forget to write it?"),
            ParseError::NotForm(s) => write!(f, "\"{}\" is not of the expected form <pos-integer>[<unit>]", s),
            ParseError::InvalidUnit(u) => write!(f, "invalid unit \"{}\"", u),
            ParseError::NegativeNotAllowed => write!(f, "negative offset specified, but only positive offsets (counts) are accepted in this context"),
            ParseError::FailedIntegerPart(a,b) => {
                // used for 0x cases
                // For length errors, they have format "0: failed to parse integer part\n    1: ..."
                // But for block-size, they have "failed to parse integer part\n\nCaused by:\n    ..."
                // We'll differentiate at higher level
                write!(f, "failed to parse integer part") // placeholder
            },
            ParseError::BlockSizeMustBePositive => write!(f, "block size argument must be positive"),
            ParseError::BlockSizeCannotUseBlock => write!(f, "can not use 'block(s)' as a unit to specify block size"),
        }
    }
}

// Helper to parse byte count for length/skip/display_offset etc.
// Returns Result<u64, ParseError> plus raw unit etc for error messages.
// For skip, we allow negative sign at front.
// For block_size, we don't allow block unit.
// The function should parse string s as byte count, using block_size value for block unit.
// For hex: if starts with "0x", parse hex integer (without unit). If remainder non-empty => integer part error.
// For decimal: parse decimal prefix then unit.

fn parse_byte_count(s: &str, block_size: u64, allow_block: bool, _for_block_size: bool) -> Result<u64, ParseError> {
    if s.is_empty() {
        return Err(ParseError::NoData);
    }
    // Check negative? This function is for positive only; caller handles sign for skip.
    if s.starts_with('-') {
        // For positive parser, negative not allowed, but we have special error for this
        // However for block_size, negative is considered NotForm, not NegativeNotAllowed
        // The caller for block_size will call this without handling sign, so we should check if starts with '-' and return NotForm for block_size case.
        // We distinguish by _for_block_size flag: if true, return NotForm
        // else return NegativeNotAllowed
        // But for length, skip, display_offset, negative should be NegativeNotAllowed
        // Let's see: For length -5, error was NegativeNotAllowed (wrapped). For block_size -5, error was NotForm.
        // So if s starts with '-', we need to decide.
        // In this function, we are called for positive parsing (after stripping sign for skip). So if we encounter '-' here, it's unexpected.
        // For length/display_offset, we want NegativeNotAllowed.
        // For block_size, we want NotForm.
        if _for_block_size {
            return Err(ParseError::NotForm(s.to_string()));
        } else {
            return Err(ParseError::NegativeNotAllowed);
        }
    }
    if s.starts_with("0x") {
        let hex_part = &s[2..];
        if hex_part.is_empty() {
            return Err(ParseError::FailedIntegerPart("empty".to_string(), "cannot parse integer from empty string".to_string()));
        }
        // Check if hex_part contains only hex digits
        // It should be all hex digits; if there's any non-hex, then integer part fails.
        // But also if there are letters beyond hex that could be unit, we should treat as integer part failure?
        // Example "0x10kB": hex_part = "10kB", contains 'k' which is not hex digit -> integer part error "invalid digit found in string"
        // So we need to attempt to parse hex_part as hex integer, but if fails due to non-hex, return FailedIntegerPart with detail "invalid digit found in string"
        // If hex_part contains only hex digits, then it's valid hex without unit.
        // So try to parse; if contains non-hex, error.
        // Also need to consider that hex digits include a-f lower case? Uppercase allowed? We saw 0xAB and 0xab both work for length? Actually we tested and 0xAB? We tested 0xAB? we tested 0xab and it worked, 0xAB? Let's check: we tested 0xAB? Not yet. But likely both lower and upper allowed for hex digits. However "0X10" is invalid because upper X, so only lower "0x".
        // For hex digits, allow 0-9 a-f A-F?
        // We saw 0xAB? Let's assume both.
        if !hex_part.chars().all(|c| c.is_ascii_hexdigit()) {
            // Find if empty string? already handled
            // Return integer part error with invalid digit
            return Err(ParseError::FailedIntegerPart("hex".to_string(), "invalid digit found in string".to_string()));
        }
        // Now parse
        match u64::from_str_radix(hex_part, 16) {
            Ok(v) => Ok(v),
            Err(e) => {
                // Could be overflow? But treat as integer part error
                // For empty, we already handled, so remaining is invalid digit?
                Err(ParseError::FailedIntegerPart("hex".to_string(), e.to_string()))
            }
        }
    } else {
        // Decimal parsing: leading decimal digits
        let mut idx = 0;
        for (i, c) in s.char_indices() {
            if c.is_ascii_digit() {
                idx = i + c.len_utf8();
            } else {
                break;
            }
        }
        if idx == 0 {
            // No leading digits
            return Err(ParseError::NotForm(s.to_string()));
        }
        let int_part = &s[..idx];
        let unit_part = &s[idx..];
        let int_val: u64 = match int_part.parse() {
            Ok(v) => v,
            Err(_) => {
                // This should not happen if digits only, but maybe overflow
                return Err(ParseError::NotForm(s.to_string()));
            }
        };
        if unit_part.is_empty() {
            Ok(int_val)
        } else {
            // Unit handling
            let unit_lower = unit_part.to_ascii_lowercase();
            let unit_original = unit_part; // preserve case for error message
            // Check if unit is block
            if unit_lower == "block" || unit_lower == "blocks" {
                if !allow_block {
                    return Err(ParseError::BlockSizeCannotUseBlock);
                }
                // Multiply by block_size
                // Check overflow
                match int_val.checked_mul(block_size) {
                    Some(v) => Ok(v),
                    None => {
                        // Overflow? Just return large? For now, cap?
                        // But hexyl probably would overflow? We'll just return max?
                        Ok(u64::MAX)
                    }
                }
            } else {
                let mult = match unit_lower.as_str() {
                    "kb" => 1000,
                    "mb" => 1_000_000,
                    "gb" => 1_000_000_000,
                    "tb" => 1_000_000_000_000,
                    "kib" => 1024,
                    "mib" => 1024*1024,
                    "gib" => 1024*1024*1024,
                    "tib" => 1024*1024*1024*1024,
                    _ => {
                        return Err(ParseError::InvalidUnit(unit_original.to_string()));
                    }
                };
                match int_val.checked_mul(mult) {
                    Some(v) => Ok(v),
                    None => Ok(u64::MAX),
                }
            }
        }
    }
}

// Wrapper that handles negative for skip
fn parse_byte_count_signed(s: &str, block_size: u64, allow_negative: bool, allow_block: bool, for_block_size: bool) -> Result<i64, ParseError> {
    if s.starts_with('-') {
        if !allow_negative {
            // Still need to parse as negative not allowed error, but ensure the error message shows the original string including minus?
            // For length=-5, error message includes "-5". So we should return NegativeNotAllowed.
            // However we need to still validate that after minus, the rest is valid positive count? For length -5, the remainder "5" is valid, but they still report negative not allowed, not invalid unit.
            // For length -foo, they report NotForm with original "-foo"? Let's check: earlier we tested --length=-foo gave "Error: failed to parse `--length` arg \"-foo\" as byte count ... \"foo\" is not of expected form"? Actually we tested length=-foo via --length=-foo gave? Let's re-run mental: we had skip -foo gave NotForm with "foo"? Wait earlier we tested skip -foo? We tested --skip=-foo gave NotForm with "foo"? Let's check earlier output: For --skip=-foo we got "Error: failed to parse `--skip` arg \"-foo\" as byte count\n\nCaused by:\n    \"foo\" is not of the expected form..." So they stripped minus for NotForm? The message showed "\"foo\"" not "\"-foo\"". For length -foo, they showed "\"foo\"" as well? Let's see: earlier for length=-foo we had "\"foo\"" as well? We had for length=-foo: Error: failed to parse `--length` arg "-foo" ... "\"foo\" is not of expected form". So they show inner "foo" without minus in cause, but outer arg includes minus.
            // For unit invalid with negative: --skip=-1M gave "invalid unit \"M\"" (without minus). So they strip minus for unit error as well.
            // For negative not allowed: they show negative not allowed cause without extra.
            // So for negative case, we should parse remainder as positive count. If remainder parsing fails, return that error (with remainder string).
            // If remainder parsing succeeds, then if allow_negative, return negative value; else return NegativeNotAllowed.
            let rest = &s[1..];
            if rest.is_empty() {
                return Err(ParseError::NotForm("".to_string())); // or NoData? Let's see: "-". What would happen? Probably NotForm.
            }
            // Check if rest starts with "0x": then parse hex etc.
            match parse_byte_count(rest, block_size, allow_block, for_block_size) {
                Ok(v) => {
                    if allow_negative {
                        // Return negative
                        // Check if v > i64::MAX ?
                        Ok(-(v as i64))
                    } else {
                        Err(ParseError::NegativeNotAllowed)
                    }
                },
                Err(e) => {
                    // For errors that involve unit or form, they should show remainder without minus in cause, but outer wrapper will show original arg with minus.
                    // So we return the error as is (which will be based on remainder).
                    Err(e)
                }
            }
        } else {
            // Actually we are in allow_negative true path for skip, we still need to handle negative.
            // The above was for allow_negative false? Let's restructure.
            unreachable!()
        }
    } else {
        // Positive
        match parse_byte_count(s, block_size, allow_block, for_block_size) {
            Ok(v) => Ok(v as i64),
            Err(e) => Err(e),
        }
    }
}

// Simpler: parse signed for skip where allow_negative true
fn parse_skip(s: &str, block_size: u64) -> Result<i64, ParseError> {
    if s.starts_with('-') {
        let rest = &s[1..];
        if rest.is_empty() {
            return Err(ParseError::NotForm(rest.to_string()));
        }
        match parse_byte_count(rest, block_size, true, false) {
            Ok(v) => Ok(-(v as i64)),
            Err(e) => Err(e),
        }
    } else {
        match parse_byte_count(s, block_size, true, false) {
            Ok(v) => Ok(v as i64),
            Err(e) => Err(e),
        }
    }
}

fn parse_length(s: &str, block_size: u64) -> Result<u64, ParseError> {
    if s.starts_with('-') {
        let rest = &s[1..];
        match parse_byte_count(rest, block_size, true, false) {
            Ok(_) => Err(ParseError::NegativeNotAllowed),
            Err(e) => {
                // If remainder fails, return that error (but outer message will include original with minus)
                // However for negative, if remainder is valid, we want NegativeNotAllowed, not the remainder's error.
                // So if remainder parsing succeeded, we return NegativeNotAllowed.
                // If remainder parsing failed, return that failure (which will be shown as cause with remainder).
                // We already handled success case above.
                // So here remainder failed:
                Err(e)
            }
        }
    } else {
        parse_byte_count(s, block_size, true, false)
    }
}

fn parse_display_offset(s: &str, block_size: u64) -> Result<u64, ParseError> {
    // Same as length: disallow negative (to match observed behavior)
    if s.starts_with('-') {
        let rest = &s[1..];
        match parse_byte_count(rest, block_size, true, false) {
            Ok(_) => Err(ParseError::NegativeNotAllowed),
            Err(e) => Err(e),
        }
    } else {
        parse_byte_count(s, block_size, true, false)
    }
}

fn parse_block_size(s: &str) -> Result<u64, ParseError> {
    // Block size parsing: no negative, no block unit, must be positive
    if s.is_empty() {
        return Err(ParseError::NoData);
    }
    if s.starts_with('-') {
        return Err(ParseError::NotForm(s.to_string()));
    }
    if s.starts_with("0x") {
        let hex_part = &s[2..];
        if hex_part.is_empty() {
            return Err(ParseError::FailedIntegerPart("empty".to_string(), "cannot parse integer from empty string".to_string()));
        }
        if !hex_part.chars().all(|c| c.is_ascii_hexdigit()) {
            return Err(ParseError::FailedIntegerPart("hex".to_string(), "invalid digit found in string".to_string()));
        }
        match u64::from_str_radix(hex_part, 16) {
            Ok(v) => {
                if v == 0 {
                    Err(ParseError::BlockSizeMustBePositive)
                } else {
                    Ok(v)
                }
            },
            Err(_) => Err(ParseError::FailedIntegerPart("hex".to_string(), "invalid digit found in string".to_string())),
        }
    } else {
        // decimal + unit
        let mut idx = 0;
        for (i, c) in s.char_indices() {
            if c.is_ascii_digit() {
                idx = i + c.len_utf8();
            } else {
                break;
            }
        }
        if idx == 0 {
            return Err(ParseError::NotForm(s.to_string()));
        }
        let int_part = &s[..idx];
        let unit_part = &s[idx..];
        let int_val: u64 = match int_part.parse() {
            Ok(v) => v,
            Err(_) => return Err(ParseError::NotForm(s.to_string())),
        };
        if int_val == 0 && unit_part.is_empty() {
            // Zero without unit is not allowed? For block size, must be positive. So 0 should give must be positive.
            return Err(ParseError::BlockSizeMustBePositive);
        }
        if unit_part.is_empty() {
            if int_val == 0 {
                Err(ParseError::BlockSizeMustBePositive)
            } else {
                Ok(int_val)
            }
        } else {
            let unit_lower = unit_part.to_ascii_lowercase();
            if unit_lower == "block" || unit_lower == "blocks" {
                return Err(ParseError::BlockSizeCannotUseBlock);
            }
            // Check if unit_lower starts with "0" etc? Already.
            // For unit "0kB" case: int_val 0 with unit => should be must be positive? Let's check earlier: block-size=0kB gave must be positive. So any 0 with unit also must be positive.
            if int_val == 0 {
                // Still must be positive, regardless of unit? Actually 0kB =0, so must be positive.
                return Err(ParseError::BlockSizeMustBePositive);
            }
            let mult = match unit_lower.as_str() {
                "kb" => 1000,
                "mb" => 1_000_000,
                "gb" => 1_000_000_000,
                "tb" => 1_000_000_000_000,
                "kib" => 1024,
                "mib" => 1024*1024,
                "gib" => 1024*1024*1024,
                "tib" => 1024*1024*1024*1024,
                _ => return Err(ParseError::InvalidUnit(unit_part.to_string())),
            };
            match int_val.checked_mul(mult) {
                Some(v) => {
                    if v == 0 {
                        Err(ParseError::BlockSizeMustBePositive)
                    } else {
                        Ok(v)
                    }
                },
                None => Ok(u64::MAX),
            }
        }
    }
}

fn main() {
    let args = Args::parse();

    // Completion handling (highest priority after color table? Actually earlier we saw color table higher than completion, but completion higher than include)
    // Priority we observed: print-color-table > completion > include > hex view
    if args.print_color_table {
        print_color_table(&args);
        return;
    }

    if let Some(shell) = args.completion {
        // Generate completion for "hexyl" binary name
        let mut cmd = Args::command();
        // Need to set bin_name to hexyl for completion generation? The clap builder for completion uses bin name from command.
        // The Args::command() has name "hexyl" already due to #[command(name="hexyl")]
        // So generate
        let bin_name = "hexyl";
        generate(shell, &mut cmd, bin_name, &mut io::stdout());
        return;
    }

    // Parse block-size
    let block_size = match parse_block_size(&args.block_size) {
        Ok(v) => v,
        Err(e) => {
            match e {
                ParseError::NoData => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                },
                ParseError::NotForm(s) => {
                    eprintln!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]", s);
                    std::process::exit(1);
                },
                ParseError::InvalidUnit(u) => {
                    eprintln!("Error: invalid unit \"{}\"", u);
                    std::process::exit(1);
                },
                ParseError::FailedIntegerPart(_, detail) => {
                    if detail == "cannot parse integer from empty string" {
                        eprintln!("Error: failed to parse integer part\n\nCaused by:\n    {}", detail);
                    } else {
                        eprintln!("Error: failed to parse integer part\n\nCaused by:\n    {}", detail);
                    }
                    std::process::exit(1);
                },
                ParseError::BlockSizeMustBePositive => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                },
                ParseError::BlockSizeCannotUseBlock => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                },
                _ => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        }
    };

    // Parse skip, length, display_offset
    let skip_opt: Option<i64> = if let Some(s) = args.skip {
        match parse_skip(&s, block_size) {
            Ok(v) => Some(v),
            Err(e) => {
                eprintln!("Error: failed to parse `--skip` arg \"{}\" as byte count", s);
                eprintln!();
                match e {
                    ParseError::NoData => {
                        eprintln!("Caused by:\n    no character data found, did you forget to write it?");
                    },
                    ParseError::NotForm(inner) => {
                        if inner.is_empty() {
                            // For "-": inner empty, but we show empty? Actually for skip -foo, inner "foo" shown.
                            // For our case, if original was "-foo", inner is "foo", but we have s = "-foo", inner = "foo"
                            // The cause should show inner without minus
                            // For empty after minus? We have inner empty string? Then NotForm with empty?
                            eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner);
                        } else {
                            eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner);
                        }
                    },
                    ParseError::InvalidUnit(u) => {
                        eprintln!("Caused by:\n    invalid unit \"{}\"", u);
                    },
                    ParseError::FailedIntegerPart(_, detail) => {
                        if detail == "cannot parse integer from empty string" {
                            eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", detail);
                        } else {
                            eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", detail);
                        }
                    },
                    _ => {
                        eprintln!("Caused by:\n    {}", e);
                    }
                }
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    let length_opt: Option<u64> = if let Some(s) = args.length {
        match parse_length(&s, block_size) {
            Ok(v) => Some(v),
            Err(e) => {
                eprintln!("Error: failed to parse `--length` arg \"{}\" as byte count", s);
                eprintln!();
                match e {
                    ParseError::NoData => {
                        eprintln!("Caused by:\n    {}", e);
                    },
                    ParseError::NotForm(inner) => {
                        eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner);
                    },
                    ParseError::InvalidUnit(u) => {
                        eprintln!("Caused by:\n    invalid unit \"{}\"", u);
                    },
                    ParseError::FailedIntegerPart(_, detail) => {
                        eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", detail);
                    },
                    ParseError::NegativeNotAllowed => {
                        eprintln!("Caused by:\n    {}", e);
                    },
                    _ => {
                        eprintln!("Caused by:\n    {}", e);
                    }
                }
                std::process::exit(1);
            }
        }
    } else {
        None
    };

    let display_offset_val: u64 = match parse_display_offset(&args.display_offset, block_size) {
        Ok(v) => v,
        Err(e) => {
            eprintln!("Error: failed to parse `--display-offset` arg \"{}\" as byte count", args.display_offset);
            eprintln!();
            match e {
                ParseError::NoData => {
                    eprintln!("Caused by:\n    {}", e);
                },
                ParseError::NotForm(inner) => {
                    eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner);
                },
                ParseError::InvalidUnit(u) => {
                    eprintln!("Caused by:\n    invalid unit \"{}\"", u);
                },
                ParseError::FailedIntegerPart(_, detail) => {
                    eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", detail);
                },
                ParseError::NegativeNotAllowed => {
                    eprintln!("Caused by:\n    {}", e);
                },
                _ => {
                    eprintln!("Caused by:\n    {}", e);
                }
            }
            std::process::exit(1);
        }
    };

    // Determine color usage
    let use_color = {
        let no_color_set = std::env::var_os("NO_COLOR").is_some();
        match args.color {
            ColorWhen::Never => false,
            ColorWhen::Force => true,
            ColorWhen::Always => {
                if no_color_set { false } else { true }
            },
            ColorWhen::Auto => {
                if no_color_set { false } else { io::stdout().is_terminal() }
            },
        }
    };

    // Plain handling
    let mut show_characters = !args.no_characters;
    // characters flag: if --characters passed, show_characters true, unless no_characters also? But clap conflicts ensure only one.
    // Actually args.characters is bool if --characters passed
    if args.characters {
        show_characters = true;
    }
    if args.no_characters {
        show_characters = false;
    }
    let mut show_position = !args.no_position;
    // args.no_position is bool

    let mut border_style = args.border;
    let mut color_when = args.color;

    if args.plain {
        // plain forces no characters and no position regardless of explicit flags
        show_characters = false;
        show_position = false;
        // For border and color, plain sets defaults but allows override? From observed behavior, plain + border unicode gives unicode, so explicit border overrides.
        // How to know if border was explicitly set? In clap, default is unicode, so we cannot distinguish if user explicitly set unicode vs default.
        // However for plain, if user explicitly sets border to unicode, we should respect it. If user does not set border, use none.
        // Since we have default, we need to detect if border was explicitly provided.
        // We can check if args.plain and border is default (unicode) -> then set to none. But if user explicitly set border to unicode, we have same value as default, so we cannot distinguish.
        // However observed: -p --border=unicode gave unicode, not none. That means when user explicitly passes --border=unicode, it should be unicode. When user doesn't pass border, -p should give none.
        // Since default is unicode, we need to know if border was set. Clap doesn't give us that easily without using ArgMatches. So we need to parse ourselves or use workaround: If plain is set, we set border to none unless user provided --border flag in raw args.
        // We'll inspect env::args() for presence of --border.
        let raw_args: Vec<String> = std::env::args().collect();
        let mut border_explicit = false;
        for arg in &raw_args {
            if arg.starts_with("--border") || arg == "-p" || arg == "--plain" {
                // crude
            }
            if arg.starts_with("--border=") || arg == "--border" {
                border_explicit = true;
            }
            // Also check short? No short for border.
        }
        // Also check for -p? Actually plain itself sets border none, but if border explicit, use explicit.
        // For simplicity, if plain true and border_explicit false, set border to none, else keep args.border (which would be explicit value).
        if !border_explicit {
            border_style = BorderStyle::None;
        }
        // Similarly for color: check if --color explicit
        let mut color_explicit = false;
        for arg in &raw_args {
            if arg.starts_with("--color=") || arg == "--color" {
                color_explicit = true;
            }
        }
        if !color_explicit {
            // plain sets color never, but our use_color will be computed from color_when.
            // If not explicit, force never.
            // So we set color_when to Never and use_color false.
            // But if color explicit, allow override (we already computed use_color based on explicit? Actually if color explicit, args.color will be that explicit value, not default always.
            // So if plain and not color_explicit, set to never.
            // We'll handle after.
        }
        // For characters and position, plain forces false regardless of explicit, so we already set false.
    }

    // Re-evaluate border and color after plain logic for overriding
    // We need more accurate detection of explicit border/color.
    // Let's use raw args scanning for simplicity.
    let raw_args: Vec<String> = std::env::args().collect();
    let mut border_explicit_value: Option<BorderStyle> = None;
    let mut color_explicit_value: Option<ColorWhen> = None;
    let mut iter = raw_args.iter().skip(1).peekable(); // skip program name
    while let Some(arg) = iter.next() {
        if arg == "--border" {
            if let Some(val) = iter.next() {
                border_explicit_value = match val.as_str() {
                    "unicode" => Some(BorderStyle::Unicode),
                    "ascii" => Some(BorderStyle::Ascii),
                    "none" => Some(BorderStyle::None),
                    _ => None,
                };
            }
        } else if arg.starts_with("--border=") {
            let val = arg.splitn(2,'=').nth(1).unwrap_or("");
            border_explicit_value = match val {
                "unicode" => Some(BorderStyle::Unicode),
                "ascii" => Some(BorderStyle::Ascii),
                "none" => Some(BorderStyle::None),
                _ => None,
            };
        } else if arg == "--color" {
            if let Some(val) = iter.next() {
                color_explicit_value = match val.as_str() {
                    "always" => Some(ColorWhen::Always),
                    "auto" => Some(ColorWhen::Auto),
                    "never" => Some(ColorWhen::Never),
                    "force" => Some(ColorWhen::Force),
                    _ => None,
                };
            }
        } else if arg.starts_with("--color=") {
            let val = arg.splitn(2,'=').nth(1).unwrap_or("");
            color_explicit_value = match val {
                "always" => Some(ColorWhen::Always),
                "auto" => Some(ColorWhen::Auto),
                "never" => Some(ColorWhen::Never),
                "force" => Some(ColorWhen::Force),
                _ => None,
            };
        }
    }

    // Determine final border
    let final_border = if args.plain {
        if let Some(b) = border_explicit_value {
            b
        } else {
            BorderStyle::None
        }
    } else {
        args.border
    };

    // Determine final color handling
    let final_color_when = if args.plain {
        if let Some(c) = color_explicit_value {
            c
        } else {
            ColorWhen::Never
        }
    } else {
        args.color
    };

    // Recompute use_color with final_color_when
    let use_color_final = {
        let no_color_set = std::env::var_os("NO_COLOR").is_some();
        match final_color_when {
            ColorWhen::Never => false,
            ColorWhen::Force => true,
            ColorWhen::Always => {
                if no_color_set { false } else { true }
            },
            ColorWhen::Auto => {
                if no_color_set { false } else { io::stdout().is_terminal() }
            },
        }
    };

    // For characters and position, plain forces false
    let final_show_chars = if args.plain { false } else { show_characters };
    let final_show_pos = if args.plain { false } else { show_position };

    // Handle include mode
    if args.include {
        handle_include(args.file, skip_opt, length_opt, block_size);
        return;
    }

    // Handle terminal width and panels
    // Parse panels option
    let panels_opt: Option<Panels> = if let Some(p_str) = args.panels {
        if p_str.to_ascii_lowercase() == "auto" {
            Some(Panels::Auto)
        } else {
            match p_str.parse::<usize>() {
                Ok(n) => {
                    if n == 0 {
                        eprintln!("Error: failed to parse `--panels` arg \"0\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type");
                        std::process::exit(1);
                    } else {
                        Some(Panels::Fixed(n))
                    }
                },
                Err(e) => {
                    // Try to parse as integer error
                    // Clap would have already handled invalid value? But we need to handle non-numeric
                    // The error for panels non-numeric was: "Error: failed to parse `--panels` arg \"foo\" as unsigned nonzero integer\n\nCaused by:\n    invalid digit found in string"
                    eprintln!("Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    {}", p_str, e);
                    std::process::exit(1);
                }
            }
        }
    } else {
        None
    };

    let terminal_width_opt: Option<usize> = if let Some(tw_str) = args.terminal_width {
        match tw_str.parse::<usize>() {
            Ok(n) => {
                if n == 0 {
                    eprintln!("error: invalid value '0' for '--terminal-width <N>': number would be zero for non-zero type\n\nFor more information, try '--help'.");
                    std::process::exit(2);
                }
                Some(n)
            },
            Err(_) => {
                // Clap handles this as invalid value error with exit 2
                // For simplicity, we rely on clap to have parsed? But we defined terminal_width as String, so we parse manually.
                // However clap would normally handle if we defined as usize. Since we defined as String, we need to produce same error format.
                // The error we saw: "error: invalid value '0' for '--terminal-width <N>': number would be zero for non-zero type"
                // For non-numeric, it would say "invalid digit found in string"
                eprintln!("error: invalid value '{}' for '--terminal-width <N>': invalid digit found in string\n\nFor more information, try '--help'.", tw_str);
                std::process::exit(2);
            }
        }
    } else {
        None
    };

    // Determine panels count
    // Need to compute width per panels for given config to determine auto.
    let group_size_val = args.group_size.as_usize();
    let base_str = match args.base {
        Base::Binary => "binary",
        Base::Octal => "octal",
        Base::Decimal => "decimal",
        Base::Hexadecimal => "hexadecimal",
    };

    let panels_count = if let Some(p) = panels_opt {
        match p {
            Panels::Fixed(n) => n,
            Panels::Auto => {
                // Determine terminal width: use terminal_size crate if available, else fallback
                let term_width = if let Some(tw) = terminal_width_opt {
                    // This case should not happen due to conflict group, but handled: if both present, error already? Actually clap will error before we get here.
                    tw
                } else {
                    get_terminal_width()
                };
                compute_max_panels(term_width, base_str, group_size_val, final_show_pos, final_show_chars)
            }
        }
    } else if let Some(tw) = terminal_width_opt {
        compute_max_panels(tw, base_str, group_size_val, final_show_pos, final_show_chars)
    } else {
        // Default: show 2 panels unless terminal not wide enough for 2
        let term_width = get_terminal_width();
        let max_panels = compute_max_panels(term_width, base_str, group_size_val, final_show_pos, final_show_chars);
        if max_panels >= 2 {
            2
        } else {
            1
        }
    };

    // Handle endianness: -e alias forces little
    let mut endianness = args.endianness;
    if args.endianness_little_alias {
        endianness = Endianness::Little;
    }

    // Now handle input reading
    let file_path = args.file;
    let mut data: Vec<u8> = Vec::new();
    let mut file_size: Option<u64> = None;
    let mut file_name: Option<String> = None;

    if let Some(ref path) = file_path {
        // Check file exists
        let metadata = match std::fs::metadata(path) {
            Ok(m) => m,
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        };
        file_size = Some(metadata.len());
        file_name = Some(path.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string());

        let mut file = match File::open(path) {
            Ok(f) => f,
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        };

        let mut skip_val: u64 = 0;
        if let Some(s) = skip_opt {
            if s >= 0 {
                skip_val = s as u64;
                // Seek
                if let Err(_) = file.seek(SeekFrom::Start(skip_val)) {
                    // If seek beyond EOF? Actually seek beyond EOF is allowed, but reading will give 0 bytes => No content
                    // But we can still seek; if fails, error
                    eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                    std::process::exit(1);
                }
            } else {
                // Negative: file_size + s
                let size = file_size.unwrap() as i64;
                let new_pos = size + s;
                if new_pos < 0 {
                    eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                    std::process::exit(1);
                }
                skip_val = new_pos as u64;
                if let Err(_) = file.seek(SeekFrom::Start(skip_val)) {
                    eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                    std::process::exit(1);
                }
            }
        }

        // Read with length limit
        if let Some(len) = length_opt {
            let mut buf = vec![0u8; len as usize];
            let bytes_read = match file.read(&mut buf) {
                Ok(n) => n,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            };
            buf.truncate(bytes_read);
            data = buf;
        } else {
            // Read all
            if let Err(e) = file.read_to_end(&mut data) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        // stdin
        let mut stdin = io::stdin();
        // Handle skip
        if let Some(s) = skip_opt {
            if s < 0 {
                eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe).");
                std::process::exit(1);
            } else {
                // Discard s bytes
                let mut discard = s as u64;
                let mut buf = [0u8; 8192];
                while discard > 0 {
                    let to_read = std::cmp::min(discard, buf.len() as u64) as usize;
                    match stdin.read(&mut buf[..to_read]) {
                        Ok(0) => break,
                        Ok(n) => {
                            discard -= n as u64;
                        },
                        Err(e) => {
                            eprintln!("Error: {}", e);
                            std::process::exit(1);
                        }
                    }
                }
            }
        }
        if let Some(len) = length_opt {
            let mut buf = vec![0u8; len as usize];
            let mut total_read = 0;
            while total_read < len as usize {
                let to_read = (len as usize) - total_read;
                let n = match stdin.read(&mut buf[total_read..total_read+to_read]) {
                    Ok(n) => n,
                    Err(e) => {
                        eprintln!("Error: {}", e);
                        std::process::exit(1);
                    }
                };
                if n == 0 { break; }
                total_read += n;
            }
            buf.truncate(total_read);
            data = buf;
        } else {
            if let Err(e) = stdin.read_to_end(&mut data) {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    }

    // Adjust display_offset for file size? In original, display_offset is added to displayed position, but if display_offset includes block unit etc, we've parsed.
    // Also need to handle display_offset for empty? It just adds.
    // For file, display_offset is added to file position (skip). So displayed offset = skip + display_offset? Actually from observed: file alphabet (26 bytes), skip 5, display_offset 10 gave offset f (15). Yes: skip 5 + offset 10 =15 (0xf). Let's verify: earlier test --skip=5 --display-offset=10 gave offset 0000000f. So displayed offset = skip + display_offset.
    // For skip negative, e.g., skip -5 (file size 26, skip 21), display_offset 0 => offset 15 (21 decimal =0x15) we saw earlier: skip -5 gave offset 00000015 (21). Yes.
    // So displayed offset base = skip (computed absolute) + display_offset.

    let base_skip = if let Some(s) = skip_opt {
        if s >= 0 {
            s as u64
        } else {
            // For file, we computed skip_val earlier, but we need to store that computed absolute skip.
            // For stdin, skip negative already errored.
            // For file, we have file_size, so we computed skip_val earlier.
            // Let's reuse logic: for file, negative skip => file_size + s
            if let Some(fs) = file_size {
                let size = fs as i64;
                let new_pos = size + s;
                if new_pos < 0 { 0 } else { new_pos as u64 }
            } else {
                0
            }
        }
    } else {
        0
    };

    let display_offset_final = base_skip + display_offset_val;

    // Now render
    let mut stdout = io::stdout();
    let render_config = RenderConfig {
        border: final_border,
        show_position: final_show_pos,
        show_characters: final_show_chars,
        character_table: args.character_table,
        color_scheme: args.color_scheme,
        group_size: group_size_val,
        endianness,
        base: args.base,
        panels: panels_count,
        display_offset: display_offset_final,
        use_color: use_color_final,
        squeezing: !args.no_squeezing,
    };

    if data.is_empty() {
        // No content handling
        render_no_content(&mut stdout, &render_config);
    } else {
        render_data(&mut stdout, &data, &render_config);
    }
}

enum Panels {
    Fixed(usize),
    Auto,
}

#[derive(Clone)]
struct RenderConfig {
    border: BorderStyle,
    show_position: bool,
    show_characters: bool,
    character_table: CharacterTable,
    color_scheme: ColorScheme,
    group_size: usize,
    endianness: Endianness,
    base: Base,
    panels: usize,
    display_offset: u64,
    use_color: bool,
    squeezing: bool,
}

fn get_terminal_width() -> usize {
    // Try to get terminal width via terminal_size crate if available, else fallback to 80
    // We will attempt to use crossterm if available? Simpler use terminal_size if feature enabled.
    #[cfg(feature = "terminal")]
    {
        if let Some((terminal_size::Width(w), _)) = terminal_size::terminal_size() {
            return w as usize;
        }
    }
    // Fallback: try ioctl via libc? We'll just return 80
    80
}

fn compute_max_panels(term_width: usize, base: &str, group: usize, show_pos: bool, show_chars: bool) -> usize {
    // Compute max panels that fit into term_width
    // Need to compute width per panels as earlier formula
    // For each possible panels from large to 1, find first that fits
    // Upper bound: maybe term_width / min_panel_width? But we can brute force up to e.g., 100 panels
    let mut max = 1;
    for p in 1..=100 {
        let w = calc_width(p, base, group, show_pos, show_chars);
        if w <= term_width {
            max = p;
        } else {
            // Since width increases with p, we can break if w > term_width and p already beyond
            // But continue maybe still? No, width monotonic increasing, so break
            if p > 1 && w > term_width {
                break;
            }
        }
    }
    max
}

fn calc_width(panels: usize, base: &str, group: usize, show_pos: bool, show_chars: bool) -> usize {
    let offset_width = if show_pos { 11 } else { 2 };
    let per = hex_width_per_panel(base, group);
    let hex_total = panels * per + (panels - 1) * 3;
    if show_chars {
        let char_total = panels * 8 + (panels - 1) + 1;
        offset_width + hex_total + 2 + char_total
    } else {
        offset_width + hex_total + 2
    }
}

fn hex_width_per_panel(base: &str, group: usize) -> usize {
    let cpb = match base {
        "binary" => 8,
        "octal" => 3,
        "decimal" => 3,
        _ => 2,
    };
    let groups = 8 / group;
    groups * (group * cpb) + (groups - 1)
}

fn render_no_content<W: Write>(w: &mut W, cfg: &RenderConfig) {
    // The No content line format depends on border
    // For border unicode: line "│        │ No content              │                         │        │        │"
    // For ascii: "│        │ No content ..."
    // For none: "│        │ No content ..."
    // Actually all have same structure: The hex panels show "No content"
    // The layout: For panels=2 (default), the top/bottom borders are constructed based on panels.
    // For empty, there is still one content line with "No content".
    // We need to construct border lines and content line.

    // For simplicity, we will generate based on panels and config
    let panels = cfg.panels;
    // For border none, we still have a single line with "│        │ No content ..."
    // Let's construct the content line for empty.

    // The content line for empty with border:
    // Need to figure out what it should be for given panels.
    // From earlier empty tests:
    //   border unicode, panels=2 default: "│        │ No content              │                         │        │        │"
    //   border ascii: same but with ASCII borders? Actually ascii empty was "+--------+-------------------------+-------------------------+--------+--------+"
    //   border none: "│        │ No content              │                         │        │        │" (same as unicode content? But with │ still)
    // For border none empty, we saw: "│        │ No content              │                         │        │        │" (with │)
    // Wait border none should have no border? But for empty, it still has │ separators? Let's check earlier: For border none empty, we saw line "│        │ No content              │                         │        │        │" which does have │. So even border none has │ for empty? That seems odd: earlier for normal data border none had no │, just spaces. But for empty, it has │. Let's verify: For border none empty, our earlier dump showed "│        │ No content ..." indeed with │. So empty case is special: It always shows vertical bars even with border none? Let's check more:
    //   For border none empty with no-position: "│ No content ..." still has │.
    //   For border none empty with no-characters: also has │.
    //   For border none empty with no-pos no-chars: "│ No content              │                         │"
    // So empty case always has at least some │ separators, even with border none.
