fn build_top_border(cfg: &RenderConfig, per: usize) -> String {
    let dash = if cfg.border == BorderStyle::Ascii { '-' } else { '─' };
    let left = if cfg.border == BorderStyle::Ascii { '+' } else { '┌' };
    let mid = if cfg.border == BorderStyle::Ascii { '+' } else { '┬' };
    let right = if cfg.border == BorderStyle::Ascii { '+' } else { '┐' };

    let mut s = String::new();
    s.push(left);
    if cfg.show_position {
        s.push_str(&dash.to_string().repeat(8));
        s.push(mid);
    }
    for i in 0..cfg.panels {
        s.push_str(&dash.to_string().repeat(per + 2));
        if i + 1 < cfg.panels {
            s.push(mid);
        } else {
            if cfg.show_characters {
                s.push(mid);
            } else {
                // last hex panel and no chars, ends
            }
        }
    }
    if cfg.show_characters {
        for j in 0..cfg.panels {
            s.push_str(&dash.to_string().repeat(8));
            if j + 1 < cfg.panels {
                s.push(mid);
            }
        }
        s.push(right);
    } else {
        // need right border
        s.push(right);
    }
    s
}

fn build_bottom_border(cfg: &RenderConfig, per: usize) -> String {
    let dash = if cfg.border == BorderStyle::Ascii { '-' } else { '─' };
    let left = if cfg.border == BorderStyle::Ascii { '+' } else { '└' };
    let mid = if cfg.border == BorderStyle::Ascii { '+' } else { '┴' };
    let right = if cfg.border == BorderStyle::Ascii { '+' } else { '┘' };

    let mut s = String::new();
    s.push(left);
    if cfg.show_position {
        s.push_str(&dash.to_string().repeat(8));
        s.push(mid);
    }
    for i in 0..cfg.panels {
        s.push_str(&dash.to_string().repeat(per + 2));
        if i + 1 < cfg.panels {
            s.push(mid);
        } else {
            if cfg.show_characters {
                s.push(mid);
            }
        }
    }
    if cfg.show_characters {
        for j in 0..cfg.panels {
            s.push_str(&dash.to_string().repeat(8));
            if j + 1 < cfg.panels {
                s.push(mid);
            }
        }
        s.push(right);
    } else {
        s.push(right);
    }
    s
}

fn build_empty_content(cfg: &RenderConfig, per: usize) -> String {
    // Always uses '│' as separator
    let sep = '│';
    let mut s = String::new();
    s.push(sep);
    if cfg.show_position {
        s.push_str(&" ".repeat(8));
        s.push(sep);
    }
    for i in 0..cfg.panels {
        if i == 0 {
            // first hex panel with No content
            let no_content = "No content";
            // format with surrounding spaces
            let inner = format!("{:<width$}", no_content, width=per);
            let area = format!(" {} ", inner); // per+2
            s.push_str(&area);
        } else {
            s.push_str(&" ".repeat(per+2));
        }
        s.push(sep);
    }
    if cfg.show_characters {
        for _ in 0..cfg.panels {
            s.push_str(&" ".repeat(8));
            s.push(sep);
        }
    }
    // Note: For border none, this line still has leading and trailing │, as observed
    // For case where show_position false and show_characters false and panels=1, what does empty look like? Let's attempt.
