fn format_byte(b: u8, base: Base) -> String {
    match base {
        Base::Binary => format!("{:08b}", b),
        Base::Octal => format!("{:03o}", b),
        Base::Decimal => format!("{:03}", b),
        Base::Hexadecimal => format!("{:02x}", b),
    }
}

fn hex_visible_len(panel_bytes: &[u8], cfg: &RenderConfig) -> usize {
    // Compute visible length of hex panel (without color codes) for padding
    // This is similar to hex_width but for partial panels, width is based on actual bytes present, not full 8?
    // For full panel (8 bytes), visible length = hex_width_per_panel
    // For partial panel with n bytes (<8), visible length = ?
    // For group size 1, with n bytes: n*2 + (n-1) spaces (if n>0) for hex base, etc.
    // For group size >1, need to compute groups for partial.
    if panel_bytes.is_empty() {
        return 0;
    }
    let cpb = match cfg.base {
        Base::Binary => 8,
        Base::Octal => 3,
        Base::Decimal => 3,
        Base::Hexadecimal => 2,
    };
    let mut visible = 0;
    let mut idx = 0;
    let mut group_count = 0;
    while idx < panel_bytes.len() {
        let group_end = std::cmp::min(idx + cfg.group_size, panel_bytes.len());
        let group_len = group_end - idx;
        // group visible = group_len * cpb
        visible += group_len * cpb;
        group_count += 1;
        idx += cfg.group_size;
    }
    // Add spaces between groups
    if group_count > 1 {
        visible += group_count - 1;
    }
    visible
}

