#[derive(Parser, Debug)]
#[command(name = "hexyl", version = "0.16.0", about = "A command-line hex viewer", bin_name = "hexyl", override_usage = "hexyl [OPTIONS] [FILE]")]
#[command(group(ArgGroup::new("width").args(&["panels","terminal_width"]).multiple(false)))]
struct Args {
    #[arg(value_name = "FILE", help = "The file to display. If no FILE argument is given, read from STDIN")]
    file: Option<PathBuf>,

    #[arg(short = 'n', long = "length", value_name = "N", aliases = ["bytes"], short_aliases = ['c','l'], help = "Only read N bytes from the input. The N argument can also include a unit with a decimal prefix (kB, MB, ..) or binary prefix (kiB, MiB, ..), or can be specified using a hex number. The short option '-l' can be used as an alias.\nExamples: --length=64, --length=4KiB, --length=0xff")]
    length: Option<String>,

    #[arg(short = 's', long = "skip", value_name = "N", help = "Skip the first N bytes of the input. The N argument can also include a unit (see `--length` for details).\nA negative value is valid and will seek from the end of the file.")]
    skip: Option<String>,

    #[arg(long = "block-size", value_name = "SIZE", default_value = "512", help = "Sets the size of the `block` unit to SIZE.\nExamples: --block-size=1024, --block-size=4kB")]
    block_size: String,

    #[arg(short = 'v', long = "no-squeezing", help = "Displays all input data. Otherwise any number of groups of output lines which would be identical to the preceding group of lines, are replaced with a line comprised of a single asterisk")]
    no_squeezing: bool,

    #[arg(long = "color", value_name = "WHEN", default_value = "always", help = "When to use colors")]
    color: ColorWhen,

    #[arg(long = "border", value_name = "STYLE", default_value = "unicode", help = "Whether to draw a border")]
    border: BorderStyle,

    #[arg(short = 'p', long = "plain", help = "Display output with --no-characters, --no-position, --border=none, and --color=never")]
    plain: bool,

    #[arg(long = "no-characters", help = "Do not show the character panel on the right")]
    no_characters: bool,

    #[arg(short = 'C', long = "characters", help = "Show the character panel on the right. This is the default, unless --no-characters has been specified")]
    characters: bool,

    #[arg(long = "character-table", value_name = "FORMAT", default_value = "default", help = "Defines how bytes are mapped to characters")]
    character_table: CharacterTable,

    #[arg(long = "color-scheme", value_name = "FORMAT", default_value = "default", help = "Defines the color scheme for the characters")]
    color_scheme: ColorScheme,

    #[arg(short = 'P', long = "no-position", help = "Whether to display the position panel on the left")]
    no_position: bool,

    #[arg(short = 'o', long = "display-offset", value_name = "N", default_value = "0", help = "Add N bytes to the displayed file position. The N argument can also include a unit (see `--length` for details).\nA negative value is valid and calculates an offset relative to the end of the file.")]
    display_offset: String,

    #[arg(long = "panels", value_name = "N", help = "Sets the number of hex data panels to be displayed. `--panels=auto` will display the maximum number of hex data panels based on the current terminal width. By default, hexyl will show two panels, unless the terminal is not wide enough for that")]
    panels: Option<String>,

    #[arg(short = 'g', long = "group-size", value_name = "N", default_value = "1", alias = "groupsize", help = "Number of bytes/octets that should be grouped together. You can use the '--endianness' option to control the ordering of the bytes within a group. '--groupsize' can be used as an alias (xxd-compatibility)")]
    group_size: GroupSize,

    #[arg(long = "endianness", value_name = "FORMAT", default_value = "big", help = "Whether to print out groups in little-endian or big-endian format. This option only has an effect if the '--group-size' is larger than 1. '-e' can be used as an alias for '--endianness=little'")]
    endianness: Endianness,

    #[arg(short = 'e', help = "An alias for '--endianness=little'", action = clap::ArgAction::SetTrue)]
    endianness_little_alias: bool,

    #[arg(short = 'b', long = "base", value_name = "B", default_value = "hexadecimal", help = "Sets the base used for the bytes. The possible options are binary, octal, decimal, and hexadecimal")]
    base: Base,

    #[arg(long = "terminal-width", value_name = "N", help = "Sets the number of terminal columns to be displayed. Since the terminal width may not be an evenly divisible by the width per hex data column, this will use the greatest number of hex data panels that can fit in the requested width but still leave some space to the right. Cannot be used with other width-setting options.")]
    terminal_width: Option<String>,

    #[arg(long = "print-color-table", help = "Print a table showing how different types of bytes are colored", action = clap::ArgAction::SetTrue)]
    print_color_table: bool,

    #[arg(short = 'i', long = "include", help = "Output in C include file style", action = clap::ArgAction::SetTrue)]
    include: bool,

    #[arg(long = "completion", value_name = "SHELL", help = "Show shell completion for a certain shell")]
    completion: Option<Shell>,
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
enum ColorWhen { Always, Auto, Never, Force }

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
enum BorderStyle { Unicode, Ascii, None }

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
enum CharacterTable {
    Default,
    Ascii,
    #[value(name = "codepage-1047")]
    Codepage1047,
    #[value(name = "codepage-437")]
    Codepage437,
    Braille,
}

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
enum ColorScheme { Default, Gradient }

#[derive(Copy, Clone, Debug, PartialEq, Eq, ValueEnum)]
enum GroupSize {
    #[value(name = "1")] One,
    #[value(name = "2")] Two,
