    #[value(name = "decimal", alias = "d", alias = "dec")]
    Decimal,
    #[value(name = "hexadecimal", alias = "x", alias = "hex")]
    Hexadecimal,
}

#[derive(Debug)]
enum ParseError {
    NoData,
    NotForm(String),
    InvalidUnit(String),
    NegativeNotAllowed,
    FailedIntegerPart(String),
    BlockSizeMustBePositive,
    BlockSizeCannotUseBlock,
}
impl std::fmt::Display for ParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ParseError::NoData => write!(f, "no character data found, did you forget to write it?"),
            ParseError::NotForm(s) => write!(f, "\"{}\" is not of the expected form <pos-integer>[<unit>]", s),
            ParseError::InvalidUnit(u) => write!(f, "invalid unit \"{}\"", u),
            ParseError::NegativeNotAllowed => write!(f, "negative offset specified, but only positive offsets (counts) are accepted in this context"),
            ParseError::FailedIntegerPart(d) => write!(f, "{}", d),
            ParseError::BlockSizeMustBePositive => write!(f, "block size argument must be positive"),
            ParseError::BlockSizeCannotUseBlock => write!(f, "can not use 'block(s)' as a unit to specify block size"),
        }
    }
}

fn parse_byte_count(s: &str, block_size: u64, allow_block: bool, for_block_size: bool) -> Result<u64, ParseError> {
    if s.is_empty() { return Err(ParseError::NoData); }
    if s.starts_with('-') {
        if for_block_size { return Err(ParseError::NotForm(s.to_string())); } else { return Err(ParseError::NegativeNotAllowed); }
    }
    if s.starts_with("0x") {
        let hex_part = &s[2..];
        if hex_part.is_empty() {
            return Err(ParseError::FailedIntegerPart("cannot parse integer from empty string".to_string()));
        }
        if !hex_part.chars().all(|c| c.is_ascii_hexdigit()) {
            return Err(ParseError::FailedIntegerPart("invalid digit found in string".to_string()));
        }
        match u64::from_str_radix(hex_part, 16) {
            Ok(v) => Ok(v),
            Err(_) => Err(ParseError::FailedIntegerPart("invalid digit found in string".to_string())),
        }
    } else {
        let mut idx = 0;
        for (i, c) in s.char_indices() {
            if c.is_ascii_digit() { idx = i + c.len_utf8(); } else { break; }
        }
        if idx == 0 { return Err(ParseError::NotForm(s.to_string())); }
        let int_part = &s[..idx];
        let unit_part = &s[idx..];
        let int_val: u64 = int_part.parse().unwrap_or(0);
        if unit_part.is_empty() { Ok(int_val) } else {
            let unit_lower = unit_part.to_ascii_lowercase();
            let unit_original = unit_part;
            if unit_lower == "block" || unit_lower == "blocks" {
                if !allow_block { return Err(ParseError::BlockSizeCannotUseBlock); }
                Ok(int_val.checked_mul(block_size).unwrap_or(u64::MAX))
            } else {
                let mult = match unit_lower.as_str() {
                    "kb" => 1000,
                    "mb" => 1_000_000,
                    "gb" => 1_000_000_000,
                    "tb" => 1_000_000_000_000,
                    "kib" => 1024,
                    "mib" => 1024*1024,
                    "gib" => 1024*1024*1024,
                    "tib" => 1024*1024*1024*1024,
                    _ => return Err(ParseError::InvalidUnit(unit_original.to_string())),
                };
                Ok(int_val.checked_mul(mult).unwrap_or(u64::MAX))
            }
        }
    }
}

fn parse_skip(s: &str, block_size: u64) -> Result<i64, ParseError> {
    if s.starts_with('-') {
        let rest = &s[1..];
        if rest.is_empty() { return Err(ParseError::NotForm(rest.to_string())); }
        match parse_byte_count(rest, block_size, true, false) {
            Ok(v) => Ok(-(v as i64)),
            Err(e) => Err(e),
        }
    } else {
        Ok(parse_byte_count(s, block_size, true, false)? as i64)
    }
}

fn parse_length(s: &str, block_size: u64) -> Result<u64, ParseError> {
    if s.starts_with('-') {
        let rest = &s[1..];
        match parse_byte_count(rest, block_size, true, false) {
            Ok(_) => Err(ParseError::NegativeNotAllowed),
            Err(e) => Err(e),
        }
    } else {
        parse_byte_count(s, block_size, true, false)
    }
}

fn parse_display_offset(s: &str, block_size: u64) -> Result<u64, ParseError> {
    if s.starts_with('-') {
        let rest = &s[1..];
        match parse_byte_count(rest, block_size, true, false) {
            Ok(_) => Err(ParseError::NegativeNotAllowed),
            Err(e) => Err(e),
        }
    } else {
        parse_byte_count(s, block_size, true, false)
    }
}

fn parse_block_size(s: &str) -> Result<u64, ParseError> {
    if s.is_empty() { return Err(ParseError::NoData); }
    if s.starts_with('-') { return Err(ParseError::NotForm(s.to_string())); }
    if s.starts_with("0x") {
        let hex_part = &s[2..];
        if hex_part.is_empty() { return Err(ParseError::FailedIntegerPart("cannot parse integer from empty string".to_string())); }
        if !hex_part.chars().all(|c| c.is_ascii_hexdigit()) { return Err(ParseError::FailedIntegerPart("invalid digit found in string".to_string())); }
        match u64::from_str_radix(hex_part, 16) {
            Ok(v) => if v==0 { Err(ParseError::BlockSizeMustBePositive) } else { Ok(v) },
            Err(_) => Err(ParseError::FailedIntegerPart("invalid digit found in string".to_string())),
        }
    } else {
        let mut idx=0;
        for (i,c) in s.char_indices() { if c.is_ascii_digit() { idx=i+c.len_utf8(); } else { break; } }
        if idx==0 { return Err(ParseError::NotForm(s.to_string())); }
        let int_part=&s[..idx];
        let unit_part=&s[idx..];
        let int_val: u64 = int_part.parse().unwrap();
        if int_val==0 && unit_part.is_empty() { return Err(ParseError::BlockSizeMustBePositive); }
        if unit_part.is_empty() {
            if int_val==0 { Err(ParseError::BlockSizeMustBePositive) } else { Ok(int_val) }
        } else {
            let unit_lower=unit_part.to_ascii_lowercase();
            if unit_lower=="block" || unit_lower=="blocks" { return Err(ParseError::BlockSizeCannotUseBlock); }
            if int_val==0 { return Err(ParseError::BlockSizeMustBePositive); }
            let mult = match unit_lower.as_str() {
                "kb"=>1000,"mb"=>1_000_000,"gb"=>1_000_000_000,"tb"=>1_000_000_000_000,
                "kib"=>1024,"mib"=>1024*1024,"gib"=>1024*1024*1024,"tib"=>1024*1024*1024*1024,
                _=> return Err(ParseError::InvalidUnit(unit_part.to_string())),
            };
            Ok(int_val.checked_mul(mult).unwrap_or(u64::MAX))
        }
    }
}

enum Panels { Fixed(usize), Auto }

#[derive(Clone)]
struct RenderConfig {
    border: BorderStyle,
    show_position: bool,
    show_characters: bool,
    character_table: CharacterTable,
    color_scheme: ColorScheme,
    group_size: usize,
    endianness: Endianness,
    base: Base,
    panels: usize,
    display_offset: u64,
    use_color: bool,
    squeezing: bool,
}

fn get_terminal_width() -> usize { 80 }

fn hex_width_per_panel(base: &str, group: usize) -> usize {
    let cpb = match base { "binary"=>8, "octal"=>3, "decimal"=>3, _=>2 };
    let groups = 8 / group;
    groups * (group * cpb) + (groups-1)
}
fn calc_width(panels: usize, base: &str, group: usize, show_pos: bool, show_chars: bool) -> usize {
    let offset_width = if show_pos { 11 } else { 2 };
    let per = hex_width_per_panel(base, group);
    let hex_total = panels * per + (panels-1)*3;
    if show_chars { offset_width + hex_total + 2 + (panels*8 + (panels-1) +1) } else { offset_width + hex_total + 2 }
}
fn compute_max_panels(term_width: usize, base: &str, group: usize, show_pos: bool, show_chars: bool) -> usize {
    let mut max=1;
    for p in 1..=100 {
        let w = calc_width(p, base, group, show_pos, show_chars);
        if w <= term_width { max=p; } else { if p>1 { break; } }
    }
    max
}

fn format_byte(b: u8, base: Base) -> String {
    match base {
        Base::Binary => format!("{:08b}", b),
        Base::Octal => format!("{:03o}", b),
        Base::Decimal => format!("{:03}", b),
        Base::Hexadecimal => format!("{:02x}", b),
    }
}
fn hex_visible_len(panel_bytes: &[u8], cfg: &RenderConfig) -> usize {
    if panel_bytes.is_empty() { return 0; }
    let cpb = match cfg.base { Base::Binary=>8, Base::Octal=>3, Base::Decimal=>3, Base::Hexadecimal=>2 };
    let mut visible=0;
    let mut idx=0;
    let mut group_count=0;
    while idx < panel_bytes.len() {
        let group_end = std::cmp::min(idx+cfg.group_size, panel_bytes.len());
        let group_len = group_end-idx;
        visible+=group_len*cpb;
        group_count+=1;
        idx+=cfg.group_size;
    }
    if group_count>1 { visible+=group_count-1; }
    visible
}

fn build_hex_panel_colored(panel_bytes: &[u8], cfg: &RenderConfig) -> String {
    if panel_bytes.is_empty() { return String::new(); }
    let mut s=String::new();
    let mut prev_color: Option<String>=None;
    let mut idx=0;
    let mut group_idx=0;
    while idx < panel_bytes.len() {
        let group_end = std::cmp::min(idx+cfg.group_size, panel_bytes.len());
        let mut group_slice: Vec<u8> = panel_bytes[idx..group_end].to_vec();
        if cfg.endianness==Endianness::Little { group_slice.reverse(); }
        if group_idx>0 { s.push(' '); }
        for b in group_slice.iter() {
            let color = if cfg.use_color { get_color_for_byte(*b, cfg) } else { String::new() };
            let need = if cfg.use_color {
                match &prev_color { Some(pc)=>pc!=&color, None=>true }
            } else { false };
            if need { s.push_str(&color); prev_color=Some(color); }
            s.push_str(&format_byte(*b, cfg.base));
        }
        group_idx+=1;
        idx+=cfg.group_size;
    }
    if cfg.use_color { s.push_str("\x1b[39m"); }
    s
}
fn build_char_panel_colored(panel_bytes: &[u8], cfg: &RenderConfig) -> String {
    if panel_bytes.is_empty() { return String::new(); }
    let mut s=String::new();
    let mut prev_color: Option<String>=None;
    for b in panel_bytes {
        let color = if cfg.use_color { get_color_for_byte(*b, cfg) } else { String::new() };
        let need = if cfg.use_color { match &prev_color { Some(pc)=>pc!=&color, None=>true } else { false } };
        if need { s.push_str(&color); prev_color=Some(color); }
        s.push(map_char(*b, cfg.character_table));
    }
    if cfg.use_color { s.push_str("\x1b[39m"); }
    s
}
fn get_offset_color() -> String {
    if let Ok(val)=std::env::var("HEXYL_COLOR_OFFSET") {
        if let Some(c)=parse_color(&val) { return c; }
    }
    "\x1b[90m".to_string()
}
fn get_color_for_byte(b: u8, cfg: &RenderConfig) -> String {
    if cfg.color_scheme==ColorScheme::Gradient { return gradient_color(b); }
    let category = if b==0x00 { "null" } else if b==0x09||b==0x0a||b==0x0b||b==0x0c||b==0x0d||b==0x20 { "whitespace" } else if b>=0x21&&b<=0x7e { "printable" } else if b<=0x7f { "other" } else { "nonascii" };
    let env_var = match category {
        "null"=>std::env::var("HEXYL_COLOR_NULL").ok(),
        "printable"=>std::env::var("HEXYL_COLOR_ASCII_PRINTABLE").ok(),
        "whitespace"=>std::env::var("HEXYL_COLOR_ASCII_WHITESPACE").ok(),
        "other"=>std::env::var("HEXYL_COLOR_ASCII_OTHER").ok(),
        "nonascii"=>std::env::var("HEXYL_COLOR_NONASCII").ok(),
        _=>None,
    };
    if let Some(val)=env_var { if let Some(c)=parse_color(&val) { return c; } }
    match category {
        "null"=>"\x1b[90m".to_string(),
        "printable"=>"\x1b[36m".to_string(),
        "whitespace"=>"\x1b[32m".to_string(),
        "other"=>"\x1b[32m".to_string(),
        "nonascii"=>"\x1b[33m".to_string(),
        _=>"\x1b[39m".to_string(),
    }
}
fn parse_color(s: &str) -> Option<String> {
    let s=s.trim();
    if s.is_empty() { return None; }
    if s.starts_with('#') {
        let hex=&s[1..];
        if hex.len()==6 {
            if let Ok(r)=u8::from_str_radix(&hex[0..2],16) {
                if let Ok(g)=u8::from_str_radix(&hex[2..4],16) {
                    if let Ok(b)=u8::from_str_radix(&hex[4..6],16) {
                        return Some(format!("\x1b[38;2;{};{};{}m",r,g,b));
                    }
                }
            }
        }
        return None;
    }
    let lower=s.to_ascii_lowercase();
    match lower.as_str() {
        "black"=>Some("\x1b[30m".to_string()),
        "red"=>Some("\x1b[31m".to_string()),
        "green"=>Some("\x1b[32m".to_string()),
        "yellow"=>Some("\x1b[33m".to_string()),
        "blue"=>Some("\x1b[34m".to_string()),
        "magenta"=>Some("\x1b[35m".to_string()),
        "cyan"=>Some("\x1b[36m".to_string()),
        "white"=>Some("\x1b[37m".to_string()),
        "bright black"=>Some("\x1b[90m".to_string()),
        "bright red"=>Some("\x1b[91m".to_string()),
        "bright green"=>Some("\x1b[92m".to_string()),
        "bright yellow"=>Some("\x1b[93m".to_string()),
        "bright blue"=>Some("\x1b[94m".to_string()),
        "bright magenta"=>Some("\x1b[95m".to_string()),
        "bright cyan"=>Some("\x1b[96m".to_string()),
        "bright white"=>Some("\x1b[97m".to_string()),
        _=>None,
    }
}
