fn print_color_table_func(use_color: bool, color_scheme: ColorScheme) {
    println!("hexyl color reference:\n");
    let categories = [
        (0x00u8, "⋄ NULL bytes (0x00)"),
        (0x41u8, "a ASCII printable characters (0x20 - 0x7E)"),
        (0x20u8, "_ ASCII whitespace (0x09 - 0x0D, 0x20)"),
        (0x01u8, "• ASCII control characters (except NULL and whitespace)"),
        (0x80u8, "× Non-ASCII bytes (0x80 - 0xFF)"),
    ];
    for (b, desc) in categories.iter() {
        let cfg = RenderConfig {
            border: BorderStyle::None,
            show_position: true,
            show_characters: true,
            character_table: CharacterTable::Default,
            color_scheme,
            group_size: 1,
            endianness: Endianness::Big,
            base: Base::Hexadecimal,
            panels: 2,
            display_offset: 0,
            use_color,
            squeezing: true,
        };
        let color = if color_scheme==ColorScheme::Gradient {
            gradient_color(*b)
        } else {
            get_color_for_byte(*b, &cfg)
        };
        if use_color {
            println!("{}{}\n\x1b[39m", color, desc);
        } else {
            println!("{}", desc);
        }
    }
}

fn handle_include(file_opt: Option<PathBuf>, skip_opt: Option<i64>, length_opt: Option<u64>, block_size: u64) {
    let mut data: Vec<u8>=Vec::new();
    let mut file_name: Option<String>=None;
    let mut file_size: Option<u64>=None;
    if let Some(ref path)=file_opt {
        let metadata = match std::fs::metadata(path) { Ok(m)=>m, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
        file_size=Some(metadata.len());
        file_name=Some(path.file_name().and_then(|s| s.to_str()).unwrap_or("").to_string());
        let mut file = match File::open(path) { Ok(f)=>f, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
        if let Some(s)=skip_opt {
            if s>=0 { let _=file.seek(SeekFrom::Start(s as u64)); }
            else {
                let size=file_size.unwrap() as i64;
                let new_pos=size+s;
                if new_pos<0 { eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."); std::process::exit(1); }
                let _=file.seek(SeekFrom::Start(new_pos as u64));
            }
        }
        if let Some(len)=length_opt {
            let mut buf=vec![0u8; len as usize];
            let n=match file.read(&mut buf) { Ok(n)=>n, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
            buf.truncate(n);
            data=buf;
        } else {
            let _=file.read_to_end(&mut data);
        }
    } else {
        let mut stdin=io::stdin();
        if let Some(s)=skip_opt {
            if s<0 { eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."); std::process::exit(1); }
            else {
                let mut discard=s as u64;
                let mut buf=[0u8;8192];
                while discard>0 {
                    let to_read=std::cmp::min(discard, buf.len() as u64) as usize;
                    match stdin.read(&mut buf[..to_read]) { Ok(0)=>break, Ok(n)=>discard-=n as u64, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } }
                }
            }
        }
        if let Some(len)=length_opt {
            let mut buf=vec![0u8; len as usize];
            let mut total=0;
            while total < len as usize {
                let to_read=(len as usize)-total;
                let n=match stdin.read(&mut buf[total..total+to_read]) { Ok(n)=>n, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
                if n==0 { break; }
                total+=n;
            }
            buf.truncate(total);
            data=buf;
        } else {
            let _=stdin.read_to_end(&mut data);
        }
    }
    let mut stdout=io::stdout();
    if let Some(fname)=file_name {
        let sanitized=sanitize_filename(&fname);
        if data.is_empty() {
            writeln!(stdout, "unsigned char {}[] = {{", sanitized).unwrap();
            writeln!(stdout, "").unwrap();
            writeln!(stdout, "}};").unwrap();
            writeln!(stdout, "unsigned int {}_len = 0;", sanitized).unwrap();
        } else {
            writeln!(stdout, "unsigned char {}[] = {{", sanitized).unwrap();
            for (i, chunk) in data.chunks(12).enumerate() {
                let mut line=String::new();
                line.push_str("  ");
                for (j,b) in chunk.iter().enumerate() {
                    line.push_str(&format!("0x{:02x}", b));
                    if i*12 + j +1 < data.len() { line.push(','); }
                    if j+1 < chunk.len() { line.push(' '); }
                }
                writeln!(stdout, "{}", line).unwrap();
            }
            writeln!(stdout, "}};").unwrap();
            writeln!(stdout, "unsigned int {}_len = {};", sanitized, data.len()).unwrap();
        }
    } else {
        if data.is_empty() { return; }
        for (i, chunk) in data.chunks(12).enumerate() {
            let mut line=String::new();
            line.push_str("  ");
            for (j,b) in chunk.iter().enumerate() {
                line.push_str(&format!("0x{:02x}", b));
                if i*12 + j +1 < data.len() { line.push(','); }
                if j+1 < chunk.len() { line.push(' '); }
            }
            writeln!(stdout, "{}", line).unwrap();
        }
    }
}
fn sanitize_filename(name: &str) -> String {
    let mut s=String::new();
    for c in name.chars() {
        if c.is_ascii_alphanumeric() || c=='_' { s.push(c); } else { s.push('_'); }
    }
    s
}
fn build_top_border(cfg: &RenderConfig, per: usize) -> String {
    let dash = if cfg.border==BorderStyle::Ascii { '-' } else { '─' };
    let left = if cfg.border==BorderStyle::Ascii { '+' } else { '┌' };
    let mid = if cfg.border==BorderStyle::Ascii { '+' } else { '┬' };
    let right = if cfg.border==BorderStyle::Ascii { '+' } else { '┐' };
    let mut s=String::new();
    s.push(left);
    if cfg.show_position { s.push_str(&dash.to_string().repeat(8)); s.push(mid); }
    for i in 0..cfg.panels {
        s.push_str(&dash.to_string().repeat(per+2));
        if i+1 < cfg.panels { s.push(mid); } else { if cfg.show_characters { s.push(mid); } }
    }
    if cfg.show_characters {
        for j in 0..cfg.panels {
            s.push_str(&dash.to_string().repeat(8));
            if j+1 < cfg.panels { s.push(mid); }
        }
        s.push(right);
    } else { s.push(right); }
    s
}
fn build_bottom_border(cfg: &RenderConfig, per: usize) -> String {
    let dash = if cfg.border==BorderStyle::Ascii { '-' } else { '─' };
    let left = if cfg.border==BorderStyle::Ascii { '+' } else { '└' };
    let mid = if cfg.border==BorderStyle::Ascii { '+' } else { '┴' };
    let right = if cfg.border==BorderStyle::Ascii { '+' } else { '┘' };
    let mut s=String::new();
    s.push(left);
    if cfg.show_position { s.push_str(&dash.to_string().repeat(8)); s.push(mid); }
    for i in 0..cfg.panels {
        s.push_str(&dash.to_string().repeat(per+2));
        if i+1 < cfg.panels { s.push(mid); } else { if cfg.show_characters { s.push(mid); } }
    }
    if cfg.show_characters {
        for j in 0..cfg.panels {
            s.push_str(&dash.to_string().repeat(8));
            if j+1 < cfg.panels { s.push(mid); }
        }
        s.push(right);
    } else { s.push(right); }
    s
}
fn build_empty_content(cfg: &RenderConfig, per: usize) -> String {
    let sep='│';
    let mut s=String::new();
    s.push(sep);
    if cfg.show_position { s.push_str(&" ".repeat(8)); s.push(sep); }
    for i in 0..cfg.panels {
        if i==0 {
            let inner=format!("{:<width$}", "No content", width=per);
            let area=format!(" {} ", inner);
            s.push_str(&area);
        } else {
            s.push_str(&" ".repeat(per+2));
        }
        s.push(sep);
    }
    if cfg.show_characters {
        for _ in 0..cfg.panels { s.push_str(&" ".repeat(8)); s.push(sep); }
    }
    s
}
fn render_no_content<W: Write>(w: &mut W, cfg: &RenderConfig) {
    let per = hex_width_per_panel(
        match cfg.base { Base::Binary=>"binary", Base::Octal=>"octal", Base::Decimal=>"decimal", Base::Hexadecimal=>"hexadecimal" },
        cfg.group_size
    );
    if cfg.border != BorderStyle::None {
        let top = build_top_border(cfg, per);
        writeln!(w, "{}", top).unwrap();
    }
    let content = build_empty_content(cfg, per);
    writeln!(w, "{}", content).unwrap();
    if cfg.border != BorderStyle::None {
        let bottom = build_bottom_border(cfg, per);
        writeln!(w, "{}", bottom).unwrap();
    }
}
fn render_data<W: Write>(w: &mut W, data: &[u8], cfg: &RenderConfig) {
    let bytes_per_line = cfg.panels * 8;
    let has_border = cfg.border != BorderStyle::None;
    if has_border {
        let per = hex_width_per_panel(
            match cfg.base { Base::Binary=>"binary", Base::Octal=>"octal", Base::Decimal=>"decimal", Base::Hexadecimal=>"hexadecimal" },
            cfg.group_size
        );
        let top = build_top_border(cfg, per);
        writeln!(w, "{}", top).unwrap();
    }
    let mut prev_line: Option<Vec<u8>>=None;
    let mut squeezing=false;
    let total_lines = (data.len() + bytes_per_line -1)/bytes_per_line;
    for chunk_idx in 0..total_lines {
        let start = chunk_idx*bytes_per_line;
        let end = std::cmp::min(start+bytes_per_line, data.len());
        let chunk = &data[start..end];
        if cfg.squeezing {
            if let Some(ref prev)=prev_line {
                if chunk.len()==bytes_per_line && prev.len()==bytes_per_line && chunk==prev.as_slice() {
                    if !squeezing { render_asterisk_line(w, cfg); squeezing=true; }
                    continue;
                } else { squeezing=false; }
            }
            prev_line=Some(chunk.to_vec());
        }
        render_line(w, cfg, chunk_idx, chunk, bytes_per_line);
    }
    if cfg.squeezing && squeezing {
        let final_offset = cfg.display_offset + data.len() as u64;
        render_line_empty(w, cfg, final_offset);
    }
    if has_border {
        let per = hex_width_per_panel(
            match cfg.base { Base::Binary=>"binary", Base::Octal=>"octal", Base::Decimal=>"decimal", Base::Hexadecimal=>"hexadecimal" },
            cfg.group_size
        );
        let bottom = build_bottom_border(cfg, per);
        writeln!(w, "{}", bottom).unwrap();
    }
}
fn render_asterisk_line<W: Write>(w: &mut W, cfg: &RenderConfig) {
    if cfg.border==BorderStyle::None {
        let total_w = calc_width(cfg.panels,
            match cfg.base { Base::Binary=>"binary", Base::Octal=>"octal", Base::Decimal=>"decimal", Base::Hexadecimal=>"hexadecimal" },
            cfg.group_size, cfg.show_position, cfg.show_characters);
        let mut s=format!(" *");
        if total_w>2 { s.push_str(&" ".repeat(total_w-2)); }
        writeln!(w, "{}", s).unwrap();
    } else {
        let per = hex_width_per_panel(
            match cfg.base { Base::Binary=>"binary", Base::Octal=>"octal", Base::Decimal=>"decimal", Base::Hexadecimal=>"hexadecimal" },
            cfg.group_size
        );
        let vertical = if cfg.border==BorderStyle::Ascii { '|' } else { '│' };
        let mut s=String::new();
        s.push(vertical);
        if cfg.show_position { s.push_str("*       "); s.push(vertical); }
        for i in 0..cfg.panels {
            s.push_str(&" ".repeat(per+2));
            if i+1 < cfg.panels { s.push(if cfg.border==BorderStyle::Ascii { '|' } else { '┊' }); } else { if cfg.show_characters { s.push(vertical); } }
        }
        if cfg.show_characters {
            for j in 0..cfg.panels {
                s.push_str(&" ".repeat(8));
                if j+1 < cfg.panels { s.push(if cfg.border==BorderStyle::Ascii { '|' } else { '┊' }); }
            }
            s.push(vertical);
        } else {
            s.push(vertical);
        }
        writeln!(w, "{}", s).unwrap();
    }
}
fn render_line_empty<W: Write>(w: &mut W, cfg: &RenderConfig, offset: u64) {
    let per = hex_width_per_panel(
        match cfg.base { Base::Binary=>"binary", Base::Octal=>"octal", Base::Decimal=>"decimal", Base::Hexadecimal=>"hexadecimal" },
        cfg.group_size
    );
    let mut line=String::new();
    match cfg.border {
        BorderStyle::None => {
            if cfg.show_position { line.push_str(&format!(" {:08x}  ", offset)); } else { line.push_str("  "); }
            for i in 0..cfg.panels {
                line.push_str(&" ".repeat(per));
                if i+1 < cfg.panels { line.push_str("   "); }
            }
            if cfg.show_characters {
                line.push_str("  ");
                for j in 0..cfg.panels {
                    line.push_str(&" ".repeat(8));
                    if j+1 < cfg.panels { line.push(' '); }
                }
                line.push(' ');
            } else { line.push_str("  "); }
        },
        BorderStyle::Unicode | BorderStyle::Ascii => {
            let vertical = if cfg.border==BorderStyle::Ascii { '|' } else { '│' };
            line.push(vertical);
            if cfg.show_position { line.push_str(&format!("{:08x}", offset)); line.push(vertical); }
            for i in 0..cfg.panels {
                line.push_str(&" ".repeat(per+2));
                if i+1 < cfg.panels { line.push(if cfg.border==BorderStyle::Ascii { '|' } else { '┊' }); } else { if cfg.show_characters { line.push(vertical); } }
            }
            if cfg.show_characters {
                for j in 0..cfg.panels {
                    line.push_str(&" ".repeat(8));
                    if j+1 < cfg.panels { line.push(if cfg.border==BorderStyle::Ascii { '|' } else { '┊' }); }
                }
                line.push(vertical);
            } else { line.push(vertical); }
        }
    }
    writeln!(w, "{}", line).unwrap();
}
fn render_line<W: Write>(w: &mut W, cfg: &RenderConfig, line_idx: usize, chunk: &[u8], bytes_per_line: usize) {
    let offset = cfg.display_offset + (line_idx * bytes_per_line) as u64;
    let per = hex_width_per_panel(
        match cfg.base { Base::Binary=>"binary", Base::Octal=>"octal", Base::Decimal=>"decimal", Base::Hexadecimal=>"hexadecimal" },
        cfg.group_size
    );
    let mut final_line=String::new();
    match cfg.border {
        BorderStyle::None => {
            if cfg.show_position {
                if cfg.use_color {
                    let c=get_offset_color();
                    final_line.push_str(&format!(" {}{}{}  ", c, format!("{:08x}", offset), "\x1b[39m"));
                } else {
                    final_line.push_str(&format!(" {:08x}  ", offset));
                }
            } else {
                final_line.push_str("  ");
            }
            for panel_idx in 0..cfg.panels {
                let start=panel_idx*8;
                if start >= chunk.len() {
                    final_line.push_str(&" ".repeat(per));
                } else {
                    let end=std::cmp::min(start+8, chunk.len());
                    let panel_bytes=&chunk[start..end];
                    let hex_with_color=build_hex_panel_colored(panel_bytes, cfg);
                    let visible_len=hex_visible_len(panel_bytes, cfg);
                    final_line.push_str(&hex_with_color);
                    if visible_len < per { final_line.push_str(&" ".repeat(per-visible_len)); }
                }
                if panel_idx+1 < cfg.panels { final_line.push_str("   "); }
            }
            if cfg.show_characters {
                final_line.push_str("  ");
                for panel_idx in 0..cfg.panels {
                    let start=panel_idx*8;
                    if start >= chunk.len() {
                        final_line.push_str(&" ".repeat(8));
                    } else {
                        let end=std::cmp::min(start+8, chunk.len());
                        let panel_bytes=&chunk[start..end];
                        let char_with_color=build_char_panel_colored(panel_bytes, cfg);
                        final_line.push_str(&char_with_color);
                        if panel_bytes.len()<8 { final_line.push_str(&" ".repeat(8-panel_bytes.len())); }
                    }
                    if panel_idx+1 < cfg.panels { final_line.push(' '); }
                }
                final_line.push(' ');
            } else { final_line.push_str("  "); }
        },
        BorderStyle::Unicode | BorderStyle::Ascii => {
            let vertical = if cfg.border==BorderStyle::Ascii { '|' } else { '│' };
            let sep_hex = if cfg.border==BorderStyle::Ascii { '|' } else { '┊' };
            let sep_char = if cfg.border==BorderStyle::Ascii { '|' } else { '┊' };
            final_line.push(vertical);
            if cfg.show_position {
                if cfg.use_color {
                    let c=get_offset_color();
                    final_line.push_str(&format!("{}{}{}", c, format!("{:08x}", offset), "\x1b[39m"));
                } else {
                    final_line.push_str(&format!("{:08x}", offset));
                }
                final_line.push(vertical);
            }
            for panel_idx in 0..cfg.panels {
                final_line.push(' ');
                let start=panel_idx*8;
                if start >= chunk.len() {
                    final_line.push_str(&" ".repeat(per));
                    final_line.push(' ');
                } else {
                    let end=std::cmp::min(start+8, chunk.len());
                    let panel_bytes=&chunk[start..end];
                    let hex_with_color=build_hex_panel_colored(panel_bytes, cfg);
                    let visible_len=hex_visible_len(panel_bytes, cfg);
                    final_line.push_str(&hex_with_color);
                    if visible_len < per { final_line.push_str(&" ".repeat(per-visible_len)); }
                    final_line.push(' ');
                }
                if panel_idx+1 < cfg.panels { final_line.push(sep_hex); } else { if cfg.show_characters { final_line.push(vertical); } }
            }
            if cfg.show_characters {
                for panel_idx in 0..cfg.panels {
                    let start=panel_idx*8;
                    if start >= chunk.len() {
                        final_line.push_str(&" ".repeat(8));
                    } else {
                        let end=std::cmp::min(start+8, chunk.len());
                        let panel_bytes=&chunk[start..end];
                        let char_with_color=build_char_panel_colored(panel_bytes, cfg);
                        final_line.push_str(&char_with_color);
                        if panel_bytes.len()<8 { final_line.push_str(&" ".repeat(8-panel_bytes.len())); }
                    }
                    if panel_idx+1 < cfg.panels { final_line.push(sep_char); }
                }
                final_line.push(vertical);
            } else {
                final_line.push(vertical);
            }
        }
    }
    writeln!(w, "{}", final_line).unwrap();
}

fn main() {
    let cli = build_cli();
    let matches = cli.get_matches();

    if matches.get_flag("print_color_table") {
        let color_str = matches.get_one::<String>("color").unwrap();
        let color = match color_str.as_str() { "always"=>ColorWhen::Always, "auto"=>ColorWhen::Auto, "never"=>ColorWhen::Never, "force"=>ColorWhen::Force, _=>ColorWhen::Always };
        let scheme_str = matches.get_one::<String>("color_scheme").unwrap();
        let scheme = match scheme_str.as_str() { "gradient"=>ColorScheme::Gradient, _=>ColorScheme::Default };
        let no_color_set = std::env::var_os("NO_COLOR").is_some();
        let use_color = match color { ColorWhen::Never=>false, ColorWhen::Force=>true, ColorWhen::Always=>!no_color_set, ColorWhen::Auto=>{ if no_color_set { false } else { std::io::stdout().is_terminal() } } };
        print_color_table_func(use_color, scheme);
        return;
    }

    if let Some(shell_str) = matches.get_one::<String>("completion") {
        let shell = match shell_str.as_str() {
            "bash"=>Shell::Bash,
            "fish"=>Shell::Fish,
            "zsh"=>Shell::Zsh,
            "elvish"=>Shell::Elvish,
            "powershell"=>Shell::PowerShell,
            _=>Shell::Bash,
        };
        let mut cmd = build_cli();
        generate(shell, &mut cmd, "hexyl", &mut io::stdout());
        return;
    }

    let block_size_str = matches.get_one::<String>("block_size").unwrap().clone();
    let block_size = match parse_block_size(&block_size_str) {
        Ok(v)=>v,
        Err(e)=>{
            match e {
                ParseError::NoData => { eprintln!("Error: {}", e); std::process::exit(1); },
                ParseError::NotForm(s) => { eprintln!("Error: \"{}\" is not of the expected form <pos-integer>[<unit>]", s); std::process::exit(1); },
                ParseError::InvalidUnit(u) => { eprintln!("Error: invalid unit \"{}\"", u); std::process::exit(1); },
                ParseError::FailedIntegerPart(d) => { eprintln!("Error: failed to parse integer part\n\nCaused by:\n    {}", d); std::process::exit(1); },
                ParseError::BlockSizeMustBePositive => { eprintln!("Error: {}", e); std::process::exit(1); },
                ParseError::BlockSizeCannotUseBlock => { eprintln!("Error: {}", e); std::process::exit(1); },
                _=>{ eprintln!("Error: {}", e); std::process::exit(1); }
            }
        }
    };

    let skip_opt: Option<i64> = if let Some(s)=matches.get_one::<String>("skip") {
        match parse_skip(s, block_size) {
            Ok(v)=>Some(v),
            Err(e)=>{
                eprintln!("Error: failed to parse `--skip` arg \"{}\" as byte count", s);
                eprintln!();
                match e {
                    ParseError::NoData=>{ eprintln!("Caused by:\n    no character data found, did you forget to write it?"); },
                    ParseError::NotForm(inner)=>{ eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner); },
                    ParseError::InvalidUnit(u)=>{ eprintln!("Caused by:\n    invalid unit \"{}\"", u); },
                    ParseError::FailedIntegerPart(d)=>{ eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", d); },
                    _=>{ eprintln!("Caused by:\n    {}", e); }
                }
                std::process::exit(1);
            }
        }
    } else { None };

    let length_opt: Option<u64> = if let Some(s)=matches.get_one::<String>("length") {
        match parse_length(s, block_size) {
            Ok(v)=>Some(v),
            Err(e)=>{
                eprintln!("Error: failed to parse `--length` arg \"{}\" as byte count", s);
                eprintln!();
                match e {
                    ParseError::NoData=>{ eprintln!("Caused by:\n    {}", e); },
                    ParseError::NotForm(inner)=>{ eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner); },
                    ParseError::InvalidUnit(u)=>{ eprintln!("Caused by:\n    invalid unit \"{}\"", u); },
                    ParseError::FailedIntegerPart(d)=>{ eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", d); },
                    ParseError::NegativeNotAllowed=>{ eprintln!("Caused by:\n    {}", e); },
                    _=>{ eprintln!("Caused by:\n    {}", e); }
                }
                std::process::exit(1);
            }
        }
    } else { None };

    let display_offset_str = matches.get_one::<String>("display_offset").unwrap().clone();
    let display_offset_val: u64 = match parse_display_offset(&display_offset_str, block_size) {
        Ok(v)=>v,
        Err(e)=>{
            eprintln!("Error: failed to parse `--display-offset` arg \"{}\" as byte count", display_offset_str);
            eprintln!();
            match e {
                ParseError::NoData=>{ eprintln!("Caused by:\n    {}", e); },
                ParseError::NotForm(inner)=>{ eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner); },
                ParseError::InvalidUnit(u)=>{ eprintln!("Caused by:\n    invalid unit \"{}\"", u); },
                ParseError::FailedIntegerPart(d)=>{ eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", d); },
                ParseError::NegativeNotAllowed=>{ eprintln!("Caused by:\n    {}", e); },
                _=>{ eprintln!("Caused by:\n    {}", e); }
            }
            std::process::exit(1);
        }
    };

    let raw_args: Vec<String> = std::env::args().collect();
    let mut border_explicit: Option<BorderStyle>=None;
    let mut color_explicit: Option<ColorWhen>=None;
    let mut iter = raw_args.iter().skip(1).peekable();
    while let Some(arg)=iter.next() {
        if arg=="--border" {
            if let Some(val)=iter.next() {
                border_explicit=match val.as_str() { "unicode"=>Some(BorderStyle::Unicode), "ascii"=>Some(BorderStyle::Ascii), "none"=>Some(BorderStyle::None), _=>None };
            }
        } else if arg.starts_with("--border=") {
            let val=arg.splitn(2,'=').nth(1).unwrap_or("");
            border_explicit=match val { "unicode"=>Some(BorderStyle::Unicode), "ascii"=>Some(BorderStyle::Ascii), "none"=>Some(BorderStyle::None), _=>None };
        } else if arg=="--color" {
            if let Some(val)=iter.next() {
                color_explicit=match val.as_str() { "always"=>Some(ColorWhen::Always), "auto"=>Some(ColorWhen::Auto), "never"=>Some(ColorWhen::Never), "force"=>Some(ColorWhen::Force), _=>None };
            }
        } else if arg.starts_with("--color=") {
            let val=arg.splitn(2,'=').nth(1).unwrap_or("");
            color_explicit=match val { "always"=>Some(ColorWhen::Always), "auto"=>Some(ColorWhen::Auto), "never"=>Some(ColorWhen::Never), "force"=>Some(ColorWhen::Force), _=>None };
        }
    }

    let plain = matches.get_flag("plain");
    let border_str = matches.get_one::<String>("border").unwrap();
    let border = match border_str.as_str() { "ascii"=>BorderStyle::Ascii, "none"=>BorderStyle::None, _=>BorderStyle::Unicode };
    let color_str = matches.get_one::<String>("color").unwrap();
    let color = match color_str.as_str() { "auto"=>ColorWhen::Auto, "never"=>ColorWhen::Never, "force"=>ColorWhen::Force, _=>ColorWhen::Always };

    let final_border = if plain {
        if let Some(b)=border_explicit { b } else { BorderStyle::None }
    } else { border };

    let final_color_when = if plain {
        if let Some(c)=color_explicit { c } else { ColorWhen::Never }
    } else { color };

    let use_color_final = {
        let no_color_set = std::env::var_os("NO_COLOR").is_some();
        match final_color_when {
            ColorWhen::Never=>false,
            ColorWhen::Force=>true,
            ColorWhen::Always=>{ if no_color_set { false } else { true } },
            ColorWhen::Auto=>{ if no_color_set { false } else { io::stdout().is_terminal() } },
        }
    };

    let no_characters = matches.get_flag("no_characters");
    let characters = matches.get_flag("characters");
    let mut show_characters = true;
    if no_characters { show_characters=false; }
    if characters { show_characters=true; }
    let no_position = matches.get_flag("no_position");
    let show_position = !no_position;

    let final_show_chars = if plain { false } else { show_characters };
    let final_show_pos = if plain { false } else { show_position };

    if matches.get_flag("include") {
        let file_opt = matches.get_one::<String>("FILE").map(|s| PathBuf::from(s));
        handle_include(file_opt, skip_opt, length_opt, block_size);
        return;
    }

    let panels_opt: Option<Panels> = if let Some(p_str)=matches.get_one::<String>("panels") {
        if p_str.to_ascii_lowercase()=="auto" { Some(Panels::Auto) }
        else {
            match p_str.parse::<usize>() {
                Ok(n)=>{
                    if n==0 { eprintln!("Error: failed to parse `--panels` arg \"0\" as unsigned nonzero integer\n\nCaused by:\n    number would be zero for non-zero type"); std::process::exit(1); }
                    Some(Panels::Fixed(n))
                },
                Err(e)=>{
                    eprintln!("Error: failed to parse `--panels` arg \"{}\" as unsigned nonzero integer\n\nCaused by:\n    {}", p_str, e);
                    std::process::exit(1);
                }
            }
        }
    } else { None };

    let terminal_width_opt: Option<usize> = if let Some(tw_str)=matches.get_one::<String>("terminal_width") {
        match tw_str.parse::<usize>() {
            Ok(n)=>{
                if n==0 { eprintln!("error: invalid value '0' for '--terminal-width <N>': number would be zero for non-zero type\n\nFor more information, try '--help'."); std::process::exit(2); }
                Some(n)
            },
            Err(_)=>{
                eprintln!("error: invalid value '{}' for '--terminal-width <N>': invalid digit found in string\n\nFor more information, try '--help'.", tw_str);
                std::process::exit(2);
            }
        }
    } else { None };

    let base_str_raw = matches.get_one::<String>("base").unwrap();
    let base = match base_str_raw.as_str() {
        "binary"|"b"|"bin"=>Base::Binary,
        "octal"|"o"|"oct"=>Base::Octal,
        "decimal"|"d"|"dec"=>Base::Decimal,
        _=>Base::Hexadecimal,
    };
    let base_str = match base { Base::Binary=>"binary", Base::Octal=>"octal", Base::Decimal=>"decimal", Base::Hexadecimal=>"hexadecimal" };
    let group_str = matches.get_one::<String>("group_size").unwrap();
    let group_size = match group_str.as_str() { "2"=>GroupSize::Two, "4"=>GroupSize::Four, "8"=>GroupSize::Eight, _=>GroupSize::One };
    let group_size_val = group_size.as_usize();

    let panels_count = if let Some(p)=panels_opt {
        match p {
            Panels::Fixed(n)=>n,
            Panels::Auto=>{
                let tw = get_terminal_width();
                compute_max_panels(tw, base_str, group_size_val, final_show_pos, final_show_chars)
            }
        }
    } else if let Some(tw)=terminal_width_opt {
        compute_max_panels(tw, base_str, group_size_val, final_show_pos, final_show_chars)
    } else {
        let tw = get_terminal_width();
        let max = compute_max_panels(tw, base_str, group_size_val, final_show_pos, final_show_chars);
        if max>=2 { 2 } else { 1 }
    };

    let endianness_str = matches.get_one::<String>("endianness").unwrap();
    let mut endianness = match endianness_str.as_str() { "little"=>Endianness::Little, _=>Endianness::Big };
    if matches.get_flag("e_alias") { endianness=Endianness::Little; }

    let file_path = matches.get_one::<String>("FILE").map(|s| PathBuf::from(s));
    let mut data: Vec<u8>=Vec::new();
    let mut file_size: Option<u64>=None;

    if let Some(ref path)=file_path {
        let metadata = match std::fs::metadata(path) { Ok(m)=>m, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
        file_size=Some(metadata.len());
        let mut file = match File::open(path) { Ok(f)=>f, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
        if let Some(s)=skip_opt {
            if s>=0 {
                let _=file.seek(SeekFrom::Start(s as u64));
            } else {
                let size=file_size.unwrap() as i64;
                let new_pos=size+s;
                if new_pos<0 { eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."); std::process::exit(1); }
                let _=file.seek(SeekFrom::Start(new_pos as u64));
            }
        }
        if let Some(len)=length_opt {
            let mut buf=vec![0u8; len as usize];
            let n=match file.read(&mut buf) { Ok(n)=>n, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
            buf.truncate(n);
            data=buf;
        } else {
            let _=file.read_to_end(&mut data);
        }
    } else {
        let mut stdin=io::stdin();
        if let Some(s)=skip_opt {
            if s<0 { eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."); std::process::exit(1); }
            else {
                let mut discard=s as u64;
                let mut buf=[0u8;8192];
                while discard>0 {
                    let to_read=std::cmp::min(discard, buf.len() as u64) as usize;
                    match stdin.read(&mut buf[..to_read]) { Ok(0)=>break, Ok(n)=>discard-=n as u64, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } }
                }
            }
        }
        if let Some(len)=length_opt {
            let mut buf=vec![0u8; len as usize];
            let mut total=0;
            while total < len as usize {
                let to_read=(len as usize)-total;
                let n=match stdin.read(&mut buf[total..total+to_read]) { Ok(n)=>n, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
                if n==0 { break; }
                total+=n;
            }
            buf.truncate(total);
            data=buf;
        } else {
            let _=stdin.read_to_end(&mut data);
        }
    }

    let base_skip = if let Some(s)=skip_opt {
        if s>=0 { s as u64 } else {
            if let Some(fs)=file_size { 
                let new_pos = fs as i64 + s;
                if new_pos<0 {0} else { new_pos as u64 }
            } else { 0 }
        }
    } else { 0 };

    let display_offset_final = base_skip + display_offset_val;

    let char_table_str = matches.get_one::<String>("character_table").unwrap();
    let character_table = match char_table_str.as_str() {
        "ascii"=>CharacterTable::Ascii,
        "codepage-1047"=>CharacterTable::Codepage1047,
        "codepage-437"=>CharacterTable::Codepage437,
        "braille"=>CharacterTable::Braille,
        _=>CharacterTable::Default,
    };
    let color_scheme_str = matches.get_one::<String>("color_scheme").unwrap();
    let color_scheme = match color_scheme_str.as_str() { "gradient"=>ColorScheme::Gradient, _=>ColorScheme::Default };

    let render_cfg = RenderConfig {
        border: final_border,
        show_position: final_show_pos,
        show_characters: final_show_chars,
        character_table,
        color_scheme,
        group_size: group_size_val,
        endianness,
        base,
        panels: panels_count,
        display_offset: display_offset_final,
        use_color: use_color_final,
        squeezing: !matches.get_flag("no_squeezing"),
    };

    let mut stdout = io::stdout();
    if data.is_empty() {
        render_no_content(&mut stdout, &render_cfg);
    } else {
        render_data(&mut stdout, &data, &render_cfg);
    }
}
