        match parse_length(s, block_size) {
            Ok(v)=>Some(v),
            Err(e)=>{
                eprintln!("Error: failed to parse `--length` arg \"{}\" as byte count", s);
                eprintln!();
                match e {
                    ParseError::NoData=>{ eprintln!("Caused by:\n    {}", e); },
                    ParseError::NotForm(inner)=>{ eprintln!("Caused by:\n    \"{}\" is not of the expected form <pos-integer>[<unit>]", inner); },
                    ParseError::InvalidUnit(u)=>{ eprintln!("Caused by:\n    invalid unit \"{}\"", u); },
                    ParseError::FailedIntegerPart(d)=>{ eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", d); },
                    ParseError::NegativeNotAllowed=>{ eprintln!("Caused by:\n    {}", e); },
                    _=>{ eprintln!("Caused by:\n    {}", e); }
                }
                std::process::exit(1);
            }
        }
    } else { None };

    let display_offset_str = matches.get_one::<String>("display_offset").unwrap().clone();
    let display_offset_val: u64 = match parse_display_offset(&display_offset_str, block_size) {
