                ParseError::InvalidUnit(u)=>{ eprintln!("Caused by:\n    invalid unit \"{}\"", u); },
                ParseError::FailedIntegerPart(d)=>{ eprintln!("Caused by:\n    0: failed to parse integer part\n    1: {}", d); },
                ParseError::NegativeNotAllowed=>{ eprintln!("Caused by:\n    {}", e); },
                _=>{ eprintln!("Caused by:\n    {}", e); }
            }
            std::process::exit(1);
        }
    };

    let raw_args: Vec<String> = std::env::args().collect();
    let mut border_explicit: Option<BorderStyle>=None;
    let mut color_explicit: Option<ColorWhen>=None;
    let mut iter = raw_args.iter().skip(1).peekable();
    while let Some(arg)=iter.next() {
        if arg=="--border" {
            if let Some(val)=iter.next() {
                border_explicit=match val.as_str() { "unicode"=>Some(BorderStyle::Unicode), "ascii"=>Some(BorderStyle::Ascii), "none"=>Some(BorderStyle::None), _=>None };
            }
        } else if arg.starts_with("--border=") {
            let val=arg.splitn(2,'=').nth(1).unwrap_or("");
            border_explicit=match val { "unicode"=>Some(BorderStyle::Unicode), "ascii"=>Some(BorderStyle::Ascii), "none"=>Some(BorderStyle::None), _=>None };
        } else if arg=="--color" {
            if let Some(val)=iter.next() {
                color_explicit=match val.as_str() { "always"=>Some(ColorWhen::Always), "auto"=>Some(ColorWhen::Auto), "never"=>Some(ColorWhen::Never), "force"=>Some(ColorWhen::Force), _=>None };
            }
        } else if arg.starts_with("--color=") {
            let val=arg.splitn(2,'=').nth(1).unwrap_or("");
            color_explicit=match val { "always"=>Some(ColorWhen::Always), "auto"=>Some(ColorWhen::Auto), "never"=>Some(ColorWhen::Never), "force"=>Some(ColorWhen::Force), _=>None };
        }
    }

    let plain = matches.get_flag("plain");
    let border_str = matches.get_one::<String>("border").unwrap();
    let border = match border_str.as_str() { "ascii"=>BorderStyle::Ascii, "none"=>BorderStyle::None, _=>BorderStyle::Unicode };
    let color_str = matches.get_one::<String>("color").unwrap();
    let color = match color_str.as_str() { "auto"=>ColorWhen::Auto, "never"=>ColorWhen::Never, "force"=>ColorWhen::Force, _=>ColorWhen::Always };

    let final_border = if plain {
        if let Some(b)=border_explicit { b } else { BorderStyle::None }
    } else { border };

