            }
        }
    } else if let Some(tw)=terminal_width_opt {
        compute_max_panels(tw, base_str, group_size_val, final_show_pos, final_show_chars)
    } else {
        let tw = get_terminal_width();
        let max = compute_max_panels(tw, base_str, group_size_val, final_show_pos, final_show_chars);
        if max>=2 { 2 } else { 1 }
    };

    let endianness_str = matches.get_one::<String>("endianness").unwrap();
    let mut endianness = match endianness_str.as_str() { "little"=>Endianness::Little, _=>Endianness::Big };
    if matches.get_flag("e_alias") { endianness=Endianness::Little; }

    let file_path = matches.get_one::<String>("FILE").map(|s| PathBuf::from(s));
    let mut data: Vec<u8>=Vec::new();
    let mut file_size: Option<u64>=None;

    if let Some(ref path)=file_path {
        let metadata = match std::fs::metadata(path) { Ok(m)=>m, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
        file_size=Some(metadata.len());
        let mut file = match File::open(path) { Ok(f)=>f, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
        if let Some(s)=skip_opt {
            if s>=0 {
                let _=file.seek(SeekFrom::Start(s as u64));
            } else {
                let size=file_size.unwrap() as i64;
                let new_pos=size+s;
                if new_pos<0 { eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."); std::process::exit(1); }
                let _=file.seek(SeekFrom::Start(new_pos as u64));
            }
        }
        if let Some(len)=length_opt {
            let mut buf=vec![0u8; len as usize];
            let n=match file.read(&mut buf) { Ok(n)=>n, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
            buf.truncate(n);
            data=buf;
        } else {
            let _=file.read_to_end(&mut data);
        }
    } else {
        let mut stdin=io::stdin();
        if let Some(s)=skip_opt {
            if s<0 { eprintln!("Error: Failed to jump to the desired input position. This could be caused by a negative offset that is too large or by an input that is not seek-able (e.g. if the input comes from a pipe)."); std::process::exit(1); }
            else {
                let mut discard=s as u64;
                let mut buf=[0u8;8192];
                while discard>0 {
                    let to_read=std::cmp::min(discard, buf.len() as u64) as usize;
                    match stdin.read(&mut buf[..to_read]) { Ok(0)=>break, Ok(n)=>discard-=n as u64, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } }
                }
            }
        }
        if let Some(len)=length_opt {
            let mut buf=vec![0u8; len as usize];
            let mut total=0;
            while total < len as usize {
                let to_read=(len as usize)-total;
                let n=match stdin.read(&mut buf[total..total+to_read]) { Ok(n)=>n, Err(e)=>{ eprintln!("Error: {}", e); std::process::exit(1); } };
                if n==0 { break; }
                total+=n;
